        SlotArtStyle(id: "clean-minimal", name: "Clean Minimal",
                     category: "Video Game Styles",
                     keywords: "flat colour with almost no shading, sparse restrained palette, simple geometric construction, generous empty space, crisp hard edges, no texture or noise, even flat lighting, iconographic simplified forms, immediate readability"),
        SlotArtStyle(id: "cold-industrial-scifi", name: "Cold Industrial Sci-Fi",
                     category: "Video Game Styles",
                     keywords: "cold blue-grey palette with emissive accent strips, brushed and anodised metal surfaces, panel seams and machined bevels, hard specular highlights on edges, functional geometric forms, controlled reflections, technical precision in every surface"),
        SlotArtStyle(id: "motion-streak", name: "Motion Streak",
                     category: "Video Game Styles",
                     keywords: "strong directional motion blur and speed streaks, stretched trailing highlights, high-contrast saturated colour, dynamic diagonal composition, sharp leading edge against a blurred tail, energetic light trails, exaggerated sense of velocity"),
    ]

    public static func byID(_ id: String?) -> SlotArtStyle? {
        guard let id, !id.isEmpty else { return nil }
        return all.first { $0.id == id }
    }

    /// Categories in their listed order, each with its styles — the order a picker shows.
    public static var byCategory: [(category: String, styles: [SlotArtStyle])] {
        var order: [String] = []
        for s in all where !order.contains(s.category) { order.append(s.category) }
        return order.map { c in (c, all.filter { $0.category == c }) }
    }

    /// Styles whose name or keywords contain `query`, for the search field.
    public static func search(_ query: String) -> [SlotArtStyle] {
        let q = query.trimmingCharacters(in: .whitespaces).lowercased()
        guard !q.isEmpty else { return all }
        return all.filter {
            $0.name.lowercased().contains(q) || $0.category.lowercased().contains(q)
                || $0.keywords.lowercased().contains(q)
        }
    }
}

public enum SlotSymbolRole: String, Sendable, CaseIterable {
    case wild, highPay, mediumPay, lowPay, scatter, bonus, jackpot
    case wysiwyg, collector, multiplier, replacement, blank, unknown
    /// SF codes cover four different jobs, and the prefix alone cannot tell them apart —
    /// the design document's own words can. See SlotSymbolRole.refined(byNote:).
    case activator, adder

    /// How the role reads to a person, for the plan table.
    public var label: String {
        switch self {
        case .wild: return "Wild"
        case .highPay: return "High pay"
        case .mediumPay: return "Medium pay"
        case .lowPay: return "Low pay"
        case .scatter: return "Scatter"
        case .bonus: return "Bonus"
        case .jackpot: return "Jackpot"
        case .wysiwyg: return "WYSIWYG value"
        case .collector: return "Collector"
        case .activator: return "Activator"
        case .adder: return "Adder"
        case .multiplier: return "Multiplier"
        case .replacement: return "Replacement"
        case .blank: return "Blank"
        case .unknown: return "Unclassified"
        }
    }

    /// The job a special-feature symbol actually does, read from what the design document
    /// says about it rather than from its code.
    ///
    /// SF is one prefix covering four jobs. Defaulting every SF to "collector" is how an
    /// adder ends up drawn as a vessel with a running total it never has. When the
    /// document does not say, collector stays the default — but it is a default, not a
    /// deduction.
    public func refined(byNote note: String) -> SlotSymbolRole {
        guard self == .collector else { return self }
        let n = note.lowercased()
        // A note that denies its verb must not be read as asserting it: "Does not
        // activate a feature" was coming back .activator.
        for d in ["does not", "doesn't", "do not", "don't", "cannot", "can't", "never ",
                  "no longer", "rather than", "instead of"] where n.contains(d) {
            return .collector
        }
        // A symbol the document calls its most valuable is a PAYING symbol, whatever its
        // code says. 4490 writes "SFs - highest value, full body, full color, full
        // frames" — those are the game's premium characters, and drawing them as
        // collector pickups throws away the document's own ranking.
        for v in ["highest value", "highest paying", "high value", "premium", "top pay",
                  "most valuable"] where n.contains(v) {
            return .highPay
        }
        // What the symbol DOES comes before what it acts on. "Collects all multiplier
        // values" is a collector; matching "multipl" first made it a multiplier, and the
        // two get drawn differently.
        // "bonus 1 collection adder" is an adder: the noun names the symbol, "collection" its target.
        if n.contains("adder") { return .adder }
        if n.contains("collect") || n.contains("gather") { return .collector }
        // "mult random", "mult all": the documents' own shorthand.
        if n.contains("multipl") || n.range(of: #"\bmult\b"#, options: .regularExpression) != nil { return .multiplier }
        if n.contains("adds ") || n.contains("adder") || n.contains("addition") { return .adder }
        if n.contains("activat") || n.contains("trigger") || n.contains("unlock") { return .activator }
        return .collector
    }

    /// Roles whose members are DELIBERATELY one family, so sharing a word between them is
    /// the design working rather than a collision.
    ///
    /// Low pays are one family by rule — all royals, or all gems, or all pebbles. Jackpots
    /// are one shared construction separated by tier colour and name, which is what
    /// shipping games do and what the art direction now demands. Reporting "chest (JP1,
    /// JP2, JP3, JP4)" as a fault told the user their correct set was broken.
    public var isFamily: Bool { self == .lowPay || self == .jackpot || self == .wysiwyg }

    /// A blank is an empty reel position. Everything else is a picture someone has to draw.
    public var needsArt: Bool { self != .blank }

    /// Rough drawing order: the symbols that set the game's look come first, so a
    /// part-finished run still shows the art that decides whether the set is working.
    public var priority: Int {
        switch self {
        case .highPay: return 0
        case .wild: return 1
        case .collector: return 2
        case .activator, .adder: return 2
        case .scatter, .bonus: return 3
        case .mediumPay: return 4
        case .jackpot: return 5
        case .wysiwyg, .multiplier: return 6
        case .lowPay: return 7
        case .replacement: return 8
        case .blank, .unknown: return 9
        }
    }
}

/// One symbol slot, as the GDD defines it.
public struct SlotSymbol: Equatable, Sendable {
    public let code: String        // "HP1", "WD1", "JP3" — the GDD's own spelling
    public let index: Int          // its symbol-set index in the GDD
    public let role: SlotSymbolRole
    public let tier: Int?          // 1 for HP1, 3 for JP3; nil when the code carries no number
    public let note: String        // the GDD's own trailing comment, verbatim

    public init(code: String, index: Int, role: SlotSymbolRole, tier: Int?, note: String) {
        self.code = code; self.index = index; self.role = role; self.tier = tier; self.note = note
    }
}

/// Reading the "Symbol Set" block out of a GDD's exported plain text.
///
/// Both real formats in the wild are handled, because both exist in the same Drive
/// folder and differ in where the code sits relative to the comment marker:
///
///     * 1-4 HP1-4        // HPs                 (4260 Dodge — code before the //)
///     - 2-5 // MPs  (Standard MP symbols)       (4400 Chevy-Hot — code after it)
///
/// The second form also names a group rather than each member, so "2-5 // MPs" has
/// to become MP1…MP4 by counting the index range. Getting that wrong silently drops
/// four symbols from the game, which is exactly the kind of quiet miscount this
/// parser exists to prevent.

/// The reels a GDD lays out, per game mode: each grid's rows and reels, and what sits around it (a hot
/// reel above, a jackpot table above, pots). Read from the document's own words — "3x5 matrix",
/// "3x3 matrix layout with an additional 1x3 Hot Reel positioned above the main matrix", "4x3 matrix
/// layout, Independent Reels". Documents write rows x reels ("3x5 lines game", 3 rows of 5 reels) but
/// not always: Chevy-Hot calls one bonus grid both "3x4" and "4x3". A size given both ways is read as
/// rows x reels with the rows the smaller (slot grids are wider than tall), and said in `notes`.
public struct ReelLayout: Equatable, Codable, Sendable {
    public struct Grid: Equatable, Codable, Sendable {
        public var mode: String          // "base", "bonus", "power bet", "loot link", "bonus 2", …
        public var rows: Int, reels: Int
        public var independent = false   // each cell its own reel (hold-and-spin style)
        public var note = ""             // the words it was read from
        /// A grid that grows ("from a 3x5 to a 5x5", "reels grow to 7 tall"): the rows it starts with. `rows`
        /// is the most it reaches, the size its bezel is built for.
        public var startRows: Int? = nil
    }
    public struct Extra: Equatable, Codable, Sendable {
        public var what: String          // "hot reel", "extra reel", "jackpot table", "pots", "meters", "wheel", "collection area"
        public var rows: Int?, reels: Int?
        public var place: String         // "above", "below", "beside"; "" when the document doesn't say
        public var count: Int? = nil     // "3 pots", two wheels
        public var mode: String? = nil   // when it belongs to one mode only
    }
    public var grids: [Grid] = []
    public var extras: [Extra] = []
    public var notes: [String] = []
    /// A prize wheel the game has ("Jackpot Wheel", "Bonus Wheel"): the labels its wedges carry, lettered as the
    /// studio letters them (GRAND, MAJOR, BONUS GAMES; "CREDITS" is a wedge left plain for the engine's
    /// number), and its wedge count when the document gives one.
    public struct Wheel: Equatable, Codable, Sendable {
        public var name: String
        public var wedges: [String]
        public var segments: Int? = nil
    }
    public var wheels: [Wheel]? = nil
    /// A pick bonus (28 of the 148 GDDs, 2026-10-06): its name as the document says it ("Jackpot Pick Game", "Snake Pick
    /// Bonus"), what its picks reveal (JACKPOTS, BONUS GAMES, CREDITS, MULTIPLIER), how many objects there are and how
    /// many the player picks when it says, what ends it ("match 3", "whammy", "lives"), and what is picked ("chests").
    public struct Pick: Equatable, Codable, Sendable {
        public var name: String
        public var reveals: [String]
        public var options: Int? = nil, picks: Int? = nil
        public var ends: String? = nil, objects: String? = nil
    }
    public var picks: [Pick]? = nil
    /// Award events the document has beyond the usual ones: "one more chance".
    public var awards: [String]? = nil
    /// The pieces Gemini found the game needs that no dedicated generator makes (ConceptPlan): meters,
    /// collection areas, glass covers, counters, …, drawn by the generic generator.
    public var concepts: [ConceptPiece]? = nil
    /// The reel set above the base grid in its housing — a hot reel, or any reel added above: the one definition
    /// the bezel's template, its brief and the game sheet share.
    public var hotReelAbove: Extra? { extras.first { ($0.what == "hot reel" || $0.what == "extra reel") && $0.place == "above" && $0.mode == nil } }
    /// What each pot unlocks, in order, as its plaque words ("EXPAND", "MULTI", "JACKPOTS OR WILDS"), when
    /// the document lists them ("the pots each unlock a feature …: a bigger matrix, …"); "" for one it
    /// names in words no plaque word fits.
    public var potFeatures: [String]? = nil
    /// How the pots look with the Power Bet on, in the GDD's words, when it gives them a look of their own (PotStates.boost).
    public var potBoost: String? = nil
    /// What the pots are (PotKind), when the document says: a chest, a safe, a piggy bank, a pot.
    public var potKind: PotKind? = nil
    /// The game's own win celebrations, lowest first, when its GDD names them (PopUps.winTiers(read:)); nil: the platform's.
    public var winTiers: [String]? = nil
    /// The base game's grid, the one the bezel is built round.
    public var base: Grid? { grids.first { $0.mode == "base" } ?? grids.first }
    /// Every grid with the name its files take, as the studio names them: base first (the grid the bezel is
    /// built round), then bonusGames, bonusGames2, powerBet, lootLink, … — "bonus games" as production says
    /// it, never "free" (the reader has already read "free games" as the bonus).
    public var fileModes: [(name: String, grid: Grid)] {
        guard let base else { return [] }
        var out: [(name: String, grid: Grid)] = [("base", base)]
        for g in grids where g != base {
            let words = g.mode.replacingOccurrences(of: #"\bbonus\b"#, with: "bonus games", options: .regularExpression).split(separator: " ")
            let n = Wording.noFreeName(words.enumerated().map { $0.offset == 0 ? $0.element.lowercased() : $0.element.prefix(1).uppercased() + $0.element.dropFirst().lowercased() }.joined())
            var name = n, i = 2
            while out.contains(where: { $0.name == name }) { name = n + "\(i)"; i += 1 }
            out.append((name, g))
        }
        return out
    }
    /// For people: "base 3×5 · bonus 3→5×5 · above: 3 pots, jackpot table".
    public var summary: String {
        var modes: [String] = []
        for m in grids.map(\.mode) where !modes.contains(m) { modes.append(m) }
        let parts = modes.map { m in "\(m) " + grids.filter { $0.mode == m }.map {
            "\($0.startRows.map { "\($0)→" } ?? "")\($0.rows)×\($0.reels)\($0.independent ? " independent" : "")" }.joined(separator: ", ") }
        let places = Dictionary(grouping: extras, by: { $0.place.isEmpty ? "around" : $0.place }).sorted { $0.key < $1.key }
            .map { "\($0.key): " + $0.value.map { e in
                (e.count.map { "\($0) " } ?? "") + e.what + ((e.count ?? 1) > 1 && !e.what.hasSuffix("s") ? "s" : "") + (e.rows.map { " \($0)×\(e.reels ?? 0)" } ?? "")
            }.joined(separator: ", ") }
        let pickParts = (picks ?? []).map { p in
            "\(p.name): " + ([p.reveals.joined(separator: "/").lowercased()] + [p.picks.map { "pick \($0)" }, p.options.map { "of \($0)" }, p.ends, p.objects].compactMap { $0 }).joined(separator: ", ")
        }
        return (parts + places + pickParts).joined(separator: " · ")
    }
}

/// Reads a GDD's reels, per game mode, and what is drawn round them. Tuned on the studio's 54 real documents
/// (Navigator --export-gdds / --read-gdd, 2026-10-04), not fixtures: the first reader, built on two documents,
/// was wrong in 48 of them. What the corpus showed:
/// - A size's mode is said before it in its own sentence ("The bonus game … is played on a 3x4 matrix"), or
///   just after it ("an 8x5 matrix during the bonus"); a feature list after it ("a 3x5 lines game with a
///   jackpot, bonus, and …") and the next sentence are about something else. "<Game> is a 3x5 … game" is base.
/// - Sizes are written rows x reels ("8x5" loot links are 8 tall) unless the sentence says otherwise ("(5
///   reels, 4 rows)") or a bonus grid is written reels first (Chevy-Hot's "3x4" bonus of the 3-reel game).
/// - Grids that grow ("from a 3x5 to a 5x5", "grow to 7 tall") are one grid, built at its largest.
/// - Hold-and-spin modes (Loot Link, Lock and Respin, …) are modes of their own, their reels independent.
/// - "N reels that are M tall", "15x1 independent reels" (15 one-cell reels: a 3x5), and phantoms: symbol
///   counts ("wy1 x5"), blast areas ("3x3 mine"), pick screens, symbol sizes.
/// - Round the reels: hot and extra reels, the jackpot table (paytable, area, meters), pots (a pot, the safe),
///   meters, wheels — never the promotions' "super boost wheel spins" copied into most documents.
/// "Free games/spins" is read as the bonus: production says "bonus games", never "free".
public enum ReelLayoutRules {
    static let numbers = ["one": 1, "single": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7,
                          "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12]
    static let num = #"(\d{1,2}|one|single|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)"#
    static func number(_ s: String) -> Int? { Int(s) ?? numbers[s.lowercased()] }
    static func re(_ p: String) -> NSRegularExpression { try! NSRegularExpression(pattern: p, options: [.caseInsensitive]) }
    /// Each match's groups ("" for a group that took no part).
    static func groups(_ r: NSRegularExpression, _ s: String) -> [(range: NSRange, g: [String])] {
        let ns = s as NSString
        return r.matches(in: s, range: NSRange(location: 0, length: ns.length)).map { m in
            (m.range, (0..<m.numberOfRanges).map { m.range(at: $0).location == NSNotFound ? "" : ns.substring(with: m.range(at: $0)) })
        }
    }

    static let modeWords = re(#"\b(super loot link|loot link|lock (?:and|&) respin|hold (?:and|&) spin|jackpot mode|drum mode|wysiwyg mode|bonus collect mode|collect mode|super boost|feature boost|super bonus|power bets?|bonus game ?(\d)\b|bonus (\d)\b|free (?:games?|spins?)|bonus(?:es)?|base)\b"#)
    /// Modes whose reels are each cell's own.
    static let holdModes: Set<String> = ["super loot link", "loot link", "lock and respin", "drum mode", "wysiwyg mode", "bonus collect mode", "collect mode"]

    /// The mode a stretch of words names, the one nearest its end winning; nil when it names none. Power bet
    /// colours what follows it: its base game is the power bet's, its bonus the power bet bonus. "Both the base
    /// and bonus" is the whole game: base.
    static func mode(named t: String) -> String? {
        let found = groups(modeWords, t).map { m -> String in
            let w = m.g[1].lowercased()
            if !m.g[2].isEmpty { return "bonus \(m.g[2])" }
            if !m.g[3].isEmpty { return "bonus \(m.g[3])" }
            if w.hasPrefix("power bet") || w == "feature boost" { return "power bet" }
            if w.hasPrefix("free") || w.hasPrefix("bonus") { return "bonus" }
            if w == "hold and spin" || w == "hold & spin" || w == "lock & respin" { return "lock and respin" }
            return w
        }
        guard let last = found.last else { return nil }
        if t.lowercased().range(of: #"\bboth (the )?base (game )?and (the )?bonus"#, options: .regularExpression) != nil { return "base" }
        if found.contains("power bet") && last != "power bet" {
            return last == "bonus" ? "power bet bonus" : last == "base" ? "power bet" : last
        }
        return last
    }

    public static func read(_ gdd: String) -> ReelLayout {
        var out = ReelLayout()
        var section = "", sectionLevel = 0, skipping: Int? = nil
        var knownReels: Int? = nil
        // The document's own word on its reels and shape, wherever it is said.
        let docReels = groups(re(#"\b(\d{1,2}) reels? (?:that are|of \d|each)|\((\d{1,2}) reels,"#), gdd).compactMap { Int($0.g[1].isEmpty ? $0.g[2] : $0.g[1]) }.first
        // A "tall" portrait game (Tall Raspberry's 8x5); "portrait only" alone is the device, not the grid (Bring 'Em In's 3x5).
        let portrait = gdd.lowercased().range(of: #"tall"? portrait"#, options: .regularExpression) != nil
        let size = re(#"(?<![A-Za-z0-9._/])(\d{1,2})\s*[x×]\s*(\d{1,2})(?![0-9_/])"#)
        let stated = re(#"\b(\d{1,2}) reels\b"#), statedRows = re(#"\b(\d{1,2}) (?:rows?|tall|high)\b"#)
        let wordGrid = re(#"\b\#(num) reels? (?:that are|of|each containing|containing|with) \#(num) (?:symbols? )?(?:tall|symbols|high|rows|positions)"#)
        let wordRange = re(#"\b\#(num) (?:variable[- ]size )?reels\b.{0,120}?\b(\d{1,2}) to (\d{1,2}) (?:tall|rows|high)"#)
        let growTall = re(#"(?:grows?|expand(?:s|ing)?|up|increases?|reach(?:es)?|growing)(?: [a-z]+){0,2} to (?:be )?(\d{1,2}) (?:tall|rows|high)|\((\d{1,2}) tall\)"#)
        let place = { (t: String) -> String in
            let l = t.lowercased()
            if l.range(of: #"\b(above|on top|top of the (screen|matrix|reels))\b"#, options: .regularExpression) != nil { return "above" }
            if l.range(of: #"\b(below|beneath|under the|bottom)\b"#, options: .regularExpression) != nil { return "below" }
            if l.range(of: #"\b(beside|to the (left|right)|either side|left of|right of|side of)\b"#, options: .regularExpression) != nil { return "beside" }
            return ""
        }
        func addExtra(_ e: ReelLayout.Extra) {
            if let i = out.extras.firstIndex(where: { $0.what == e.what && $0.mode == e.mode }) {
                if out.extras[i].place.isEmpty { out.extras[i].place = e.place }
                if let c = e.count, c > (out.extras[i].count ?? 0) { out.extras[i].count = c }
            } else { out.extras.append(e) }
        }
        func addGrid(_ g: ReelLayout.Grid) {
            if let i = out.grids.firstIndex(where: { $0.mode == g.mode && $0.rows == g.rows && $0.reels == g.reels && $0.startRows == g.startRows }) {
                out.grids[i].independent = out.grids[i].independent || g.independent    // said again, with more
                return
            }
            out.grids.append(g)
            if g.mode == "base", knownReels == nil { knownReels = g.reels }
        }

        var titled = false, wheels = Set<String>()     // the wheels' own names: "Jackpot Wheel", "Bonus Wheel"
        var wheelText: [String: String] = [:], lastWheel = "Wheel", carryWheel: String? = nil   // what is said of each wheel
        // Capitalised: a name, not "the wheel"; "Bonus Game Wheel" is the Bonus Wheel.
        let wheelName = try! NSRegularExpression(pattern: #"\b([A-Z][a-z]+)(?: Game)? Wheel\b"#)
        for raw in gdd.components(separatedBy: .newlines) {
            let trimmed = raw.trimmingCharacters(in: .whitespaces)
            let hashes = trimmed.prefix(while: { $0 == "#" }).count
            let text = String(trimmed.dropFirst(hashes)).trimmingCharacters(in: CharacterSet.whitespaces.union(CharacterSet(charactersIn: "*-•")))
            guard !text.isEmpty else { continue }
            let listItem = trimmed.hasPrefix("-") || trimmed.hasPrefix("*") || trimmed.hasPrefix("•") || trimmed.hasPrefix("//")
            let heading = hashes > 0 || (!listItem && text.count < 50 && !text.hasSuffix(".") && text.range(of: #"\d\s*[x×]\s*\d"#, options: .regularExpression) == nil)
            if heading {
                let level = hashes > 0 ? hashes : 9, l = text.lowercased()
                // Promotions, messaging and audio are about other things — the "super boost wheel spins"
                // promotion is copied into most documents. They end at a heading of their rank or above,
                // not at a short line inside them.
                if let s = skipping, hashes > 0 ? level <= s : mode(named: text) != nil { skipping = nil }
                // Section names only: "Sound Designer" in a document's credits is not its audio section.
                if l.range(of: #"^(audio|sounds?|sound (design|behaviou?rs?|effects|list)|(journey[- ]based )?promotions?|messaging)( ?[/&-] ?\w+)?\s*:?$"#, options: .regularExpression) != nil {
                    skipping = min(skipping ?? level, level); continue
                }
                guard skipping == nil else { continue }
                // The document's title ("Green Machine Deluxe Power Bet") names the game, not a section.
                guard titled else { titled = true; continue }
                if let m = mode(named: text) { section = m; sectionLevel = level }
                // A sub-heading ("Spinning & Winning" under "Bonus Game Mode") keeps its mode's section.
                else if hashes > 0 && level <= sectionLevel || hashes == 1
                            || ["presentation", "layout", "tech", "symbol", "overview", "tutorial", "math", "paytable"].contains(where: l.contains) { section = ""; sectionLevel = 0 }
                continue
            }
            titled = true
            guard skipping == nil else { continue }
            // A wheel's description continued in comment lines under it ("//11=WY1 (standard bonus), 16=WY2
            // (random wilds)"): still about that wheel.
            if let w = carryWheel, trimmed.hasPrefix("//") { wheelText[w, default: ""] += " " + text.lowercased() } else { carryWheel = nil }
            // Growing reels said across sentences: "six variable-size reels … Reels 1 and 6 can be anywhere from 3 to 10 tall".
            for w in groups(wordRange, text) {
                guard let k = number(w.g[1]), let lo = Int(w.g[2]), let hi = Int(w.g[3]), (1...12).contains(k), lo < hi, hi <= 12 else { continue }
                let m = mode(named: (text as NSString).substring(to: w.range.location)) ?? (section.isEmpty ? "base" : section)
                addGrid(ReelLayout.Grid(mode: m, rows: hi, reels: k, note: String(text.prefix(140)), startRows: lo))
            }
            // Sentences: exports run paragraphs together ("…Bonus games.The pots are …").
            let sentences = text.replacingOccurrences(of: #"(?<=[a-z0-9)”"'][.!?])\s*(?=[A-Z{])"#, with: "\u{1}", options: .regularExpression)
                .components(separatedBy: "\u{1}")
            for sentence in sentences where !sentence.isEmpty {
                let lower = sentence.lowercased(), ns = sentence as NSString
                // Independent reels, not reels that grow "independently" or an "independent jackpot reel".
                let indie = lower.range(of: #"\bindependent\b(?! (jackpot|one))"#, options: .regularExpression) != nil
                var previous: ReelLayout.Grid? = nil, previousEnd = 0
                // The mode of whatever starts at `loc`: said before it, said just after it, the headline's base, its section.
                func modeAt(_ loc: Int, after: String) -> String {
                    let before = ns.substring(to: loc)
                    // Said just after it ("a 5×6 matrix during the bonus round") beats an earlier clause's mode.
                    if let q = groups(re(#"^\s*(?:[a-z]+\s){0,3}?(?:during|in|for|of|within) the ([a-z0-9 &]{3,30})"#), after).first, let m = mode(named: q.g[1]) { return m }
                    // The game itself: "Example is a 3x5 lines game", "The game starts off as a 3x5" — its base,
                    // even when its name has a mode in it ("Green Machine … with Power Bet is a 5x5 version").
                    if let subject = groups(re(#"^\s*([^,]{1,70}?)\s+(?:is an?|starts?(?: off)? as an?|begins? (?:as|at) an?)\s+(?:[a-z'’-]+\s+){0,6}$"#), before).first?.g[1] {
                        let l = subject.lowercased()
                        if l == "the game" || l == "this game" || !(l.hasPrefix("the ") || l.hasPrefix("this ") || l.hasPrefix("each ") || l.hasPrefix("it")) { return "base" }
                    }
                    var m = mode(named: before)
                    if m == "base", section.hasPrefix("power bet") { m = section }
                    return m ?? (section.isEmpty ? "base" : section)
                }
                for match in groups(size, sentence) {
                    guard let a = Int(match.g[1]), let b = Int(match.g[2]) else { continue }
                    let end = match.range.location + match.range.length
                    let after = ns.substring(from: end).lowercased(), before = ns.substring(to: match.range.location).lowercased()
                    let soon = String(after.prefix(30))
                    // Phantoms: symbol counts ("wy1 x5" is kept out by the pattern), blast areas, masks, pick
                    // screens, a symbol's own size.
                    if soon.prefix(24).range(of: #"\b(mines?|explosion|explodes|surrounding|piece|chests?|win animation|super stack|dim|mask|pick|blast)\b"#, options: .regularExpression) != nil
                        || soon.range(of: #"^\s*(\w+\s)?(symbols?|mega|giant|colossal)\b"#, options: .regularExpression) != nil
                        || before.suffix(50).range(of: #"\b(dim|blackout|mask|blast|explosion)\b"#, options: .regularExpression) != nil { continue }
                    // Cells counted ("15x1 independent reels"): one-cell reels laid over the game's reels.
                    if b == 1, a > 4, indie {
                        let reels = knownReels ?? (a % 5 == 0 ? 5 : a % 6 == 0 ? 6 : 5)
                        guard a % reels == 0 else { continue }
                        let m = modeAt(match.range.location, after: after)
                        addGrid(ReelLayout.Grid(mode: m, rows: a / reels, reels: reels, independent: true, note: String(sentence.prefix(140))))
                        continue
                    }
                    guard (1...12).contains(a), (1...12).contains(b) else { continue }
                    let m = modeAt(match.range.location, after: after)
                    // A reel beside the grid: "an additional 1x3 Hot Reel positioned above", "a 1x5 reel to the right".
                    if soon.contains("hot reel") || soon.range(of: #"^\s*(?:\w+\s){0,2}reel\b"#, options: .regularExpression) != nil
                        && (before.range(of: #"(additional|added|addition of|extra|an? (?:sideways|horizontal))\s*(\w+\s)?$"#, options: .regularExpression) != nil
                            || soon.range(of: #"reel (to the (right|left)|on top|above|below)"#, options: .regularExpression) != nil) {
                        let at = place(soon + " " + String(after.prefix(80)))
                        let hot = soon.contains("hot reel") || lower.contains("hot reel")
                        let r = at == "beside" ? max(a, b) : min(a, b), k = at == "beside" ? min(a, b) : max(a, b)
                        addExtra(ReelLayout.Extra(what: hot ? "hot reel" : "extra reel", rows: r, reels: k, place: at.isEmpty ? "above" : at,
                                                  mode: m == "base" ? nil : m))
                        continue
                    }
                    if soon.range(of: #"^\s*(?:\w+\s){0,1}collection (area|row|bar)"#, options: .regularExpression) != nil {
                        addExtra(ReelLayout.Extra(what: "collection area", rows: min(a, b), reels: max(a, b), place: place(after), mode: m == "base" ? nil : m))
                        continue
                    }
                    let near = String(before.suffix(60)) + " " + String(after.prefix(60))
                    guard ["matrix", "matrices", "reel", "grid", "layout", "lines", "ways", "game", "stepper", "spinner", "played on", "starts", "begins", "tall"]
                            .contains(where: near.contains) else { continue }
                    // Which number is the reels: the sentence says ("(5 reels, 4 rows)"); else the game's reel
                    // count, from its base grid or the document's own words ("5 reels that are 3 tall"); else a
                    // portrait game is taller than wide, any other wider. Sizes are written both ways ("a 5x3
                    // ways game", "a 3x5 lines game"), so the order they are written in decides nothing.
                    var rows = min(a, b), reels = max(a, b)
                    if let r = groups(stated, sentence).compactMap({ Int($0.g[1]) }).first(where: { $0 == a || $0 == b }) {
                        reels = r; rows = r == b ? a : b
                    } else if let r = groups(statedRows, sentence).compactMap({ Int($0.g[1]) }).first(where: { $0 == a || $0 == b }) {
                        rows = r; reels = r == a ? b : a
                    } else if let k = knownReels ?? docReels, (a == k) != (b == k) {
                        reels = k; rows = a == k ? b : a
                    } else if portrait {
                        rows = max(a, b); reels = min(a, b)
                    }
                    var g = ReelLayout.Grid(mode: m, rows: rows, reels: reels, independent: indie || holdModes.contains(m), note: String(sentence.prefix(140)))
                    // A size this one grows from, earlier in the sentence: one grid, built at its largest.
                    if let p = previous, p.mode == g.mode, p.reels == g.reels, p.rows != g.rows,
                       ns.substring(with: NSRange(location: previousEnd, length: match.range.location - previousEnd)).lowercased()
                        .range(of: #"\b(to|grows?|expands?|upgrades?|unlocks?|transitions?|increases?|becomes?)\b"#, options: .regularExpression) != nil {
                        g.startRows = min(p.rows, g.rows); g.rows = max(p.rows, g.rows)
                    }
                    addGrid(g)
                    previous = g; previousEnd = end
                }
                // Grids written in words: "5 reels that are 3 tall", "six variable-size reels … 3 to 10 tall".
                for w in groups(wordGrid, sentence) {
                    guard let k = number(w.g[1]), let r = number(w.g[2]), (1...12).contains(k), (1...12).contains(r) else { continue }
                    addGrid(ReelLayout.Grid(mode: modeAt(w.range.location, after: ""), rows: r, reels: k, independent: indie, note: String(sentence.prefix(140))))
                }
                // A reel added above: "a seventh fixed-size reel above the matrix that tumbles sideways".
                if lower.range(of: #"\b(sixth|seventh|eighth|extra|additional|sideways|horizontal)( [a-z-]+)? reel (?:that sits |positioned |placed )?(above|on top)"#, options: .regularExpression) != nil {
                    let m = modeAt(0, after: "")
                    addExtra(ReelLayout.Extra(what: lower.contains("hot reel") ? "hot reel" : "extra reel", rows: 1, reels: nil, place: "above", mode: m == "base" ? nil : m))
                }
                // Reels that grow taller: the grid of its mode, built at the height it reaches.
                for w in groups(growTall, sentence) {
                    guard let t = Int(w.g[1].isEmpty ? w.g[2] : w.g[1]), t <= 12 else { continue }
                    let m = modeAt(w.range.location, after: "")
                    if let i = out.grids.firstIndex(where: { $0.mode == m }) ?? out.grids.firstIndex(where: { $0.mode == "base" }), t > out.grids[i].rows {
                        out.grids[i].startRows = out.grids[i].startRows ?? out.grids[i].rows; out.grids[i].rows = t
                    }
                }
                // Round the reels.
                let m = section.isEmpty ? nil : section
                if lower.range(of: #"\bjackpot (table|paytable|pay table|area|display|meters?|plaques?|banner)s?\b|\bpaytables? above"#, options: .regularExpression) != nil {
                    addExtra(ReelLayout.Extra(what: "jackpot table", rows: nil, reels: nil, place: place(lower)))
                }
                // Pots, or the vessel a game fills instead — a chest, safe, vault or piggy bank — when it sits above the reels
                // or fills (a pick bonus's chests do neither).
                let vessel = #"(chests?|coffers?|vaults?|piggy ?banks?|piggies|jars?|cauldrons?|urns?)"#
                if lower.range(of: #"\b(pots?|pot avatar|collection pot)\b|\bsafe (above|fills|at the top)|\bthe safe\b|\b(hoard|basket) (above|fills)"#, options: .regularExpression) != nil
                    || (lower.range(of: #"\b\#(vessel)\b"#, options: .regularExpression) != nil
                        && lower.range(of: #"\babove the (matrix|reels)\b|\b(fills?|filling|fill up)\b"#, options: .regularExpression) != nil
                        && lower.range(of: #"\b(pick|picks|picking|select|reveal)\b"#, options: .regularExpression) == nil) {
                    let n = groups(re(#"\b\#(num) (?:\w+ ){0,2}(?:pots|chests|coffers|safes|vaults|piggy ?banks|piggies|jars|cauldrons|urns)\b"#), lower).compactMap { number($0.g[1]) }.first
                    let singular = lower.range(of: #"\b(pots|chests|coffers|safes|vaults|piggy ?banks|piggies|jars|cauldrons|urns)\b|\bpot \d"#, options: .regularExpression) == nil
                    addExtra(ReelLayout.Extra(what: "pots", rows: nil, reels: nil, place: place(lower), count: n ?? (singular ? 1 : nil)))
                }
                if lower.range(of: #"\bmeters?\b"#, options: .regularExpression) != nil,
                   lower.range(of: #"\b(win|bet|jackpot|credit) meters?\b"#, options: .regularExpression) == nil {
                    let n = groups(re(#"\b\#(num) (?:\w+ ){0,2}meters\b"#), lower).compactMap { number($0.g[1]) }.first
                    if n != nil || !place(lower).isEmpty { addExtra(ReelLayout.Extra(what: "meters", rows: nil, reels: nil, place: place(lower), count: n, mode: m == "base" ? nil : m)) }
                }
                if lower.range(of: #"\bwheels?\b"#, options: .regularExpression) != nil,
                   lower.range(of: #"super boost wheel spin|remaining_spins"#, options: .regularExpression) == nil {
                    var named = groups(wheelName, sentence).map(\.g[1]).filter { !["The", "A", "This", "Each", "That", "Second", "First"].contains($0) }
                    // A wheel already named, said in lower case ("the winning bonus wheel wedge").
                    named += wheels.filter { w in !named.contains(w) && lower.range(of: "\\b\(w.lowercased())( game)? wheel\\b", options: .regularExpression) != nil }.sorted()
                    wheels.formUnion(named)
                    addExtra(ReelLayout.Extra(what: "wheel", rows: nil, reels: nil, place: "", count: max(1, wheels.count)))
                    // A sentence is about the wheels it names, or the last one named.
                    for w in named.isEmpty ? [lastWheel] : named.map({ "\($0) Wheel" }) { wheelText[w, default: ""] += " " + lower }
                    if let l = named.last { lastWheel = "\(l) Wheel" }
                    carryWheel = named.isEmpty ? lastWheel : "\(named.last!) Wheel"
                }
            }
        }
        // One grid per mode and width, built at its largest: "a 3x5 or a 5x5 matrix depending on …".
        var merged: [ReelLayout.Grid] = []
        for g in out.grids {
            if let i = merged.firstIndex(where: { $0.mode == g.mode && $0.reels == g.reels && $0.independent == g.independent }) {
                let lo = min(merged[i].startRows ?? merged[i].rows, g.startRows ?? g.rows), hi = max(merged[i].rows, g.rows)
                merged[i].rows = hi; merged[i].startRows = lo < hi ? lo : nil
            } else { merged.append(g) }
        }
        out.grids = merged
        if out.grids.isEmpty { out.notes.append("The document gives no reel size.") }
        // Each wheel's wedges, from what is said of it ("Wheel" alone folds into the first named one).
        if !wheelText.isEmpty {
            if let unnamed = wheelText.removeValue(forKey: "Wheel") {
                let first = wheelText.keys.sorted().first ?? "Wheel"
                wheelText[first, default: ""] += unnamed
            }
            out.wheels = wheelText.keys.sorted { a, b in a.hasPrefix("Bonus") == b.hasPrefix("Bonus") ? a < b : !a.hasPrefix("Bonus") }
                .map { WheelRules.wheel(named: $0, text: wheelText[$0]!) }
        }
        let picks = PickRules.read(gdd)
        if !picks.isEmpty { out.picks = picks }
        if gdd.lowercased().contains("one more chance") { out.awards = ["one more chance"] }
        if let pots = out.extras.first(where: { $0.what == "pots" }), (pots.count ?? 0) > 1 { out.potFeatures = PotStates.features(gdd, count: pots.count!) }
        if out.extras.contains(where: { $0.what == "pots" }) {
            out.potBoost = PotStates.boost(gdd)
            // What they are: the vessel word in the lines that speak of them filling or sitting above the reels.
            let lines = gdd.components(separatedBy: .newlines).filter { $0.range(of: #"(?i)\b(fill|fills|filling|collect|collects|above the (matrix|reels)|feeds?)\b"#, options: .regularExpression) != nil }
            out.potKind = lines.lazy.compactMap { PotKind.read($0) }.first
        }
        out.winTiers = PopUps.winTiers(read: gdd)
        return out
    }
}

/// The reel area a GDD's grid needs — its bezel (the frame round the reels), the dividers between reels
/// and the reel texture behind them — laid out in code, exactly, before any art: the model paints the
/// material, never the geometry (what the symbol frames taught). Ratios measured on the studio's shipped
/// games (about 25: B2B packs, artSource PSDs, screenshots; 2026-10-04), in cells: side band 0.20 (middle
/// half 0.14–0.30), divider 0.045, backing 0.05 under the band, corner radius 0.1, a crest above the top
/// band 0.3–0.6. A hot reel above sits in a housing sharing the top band (DeluxeWays' notched box).
public struct ReelArea: Equatable, Sendable {
    public struct Rect: Equatable, Sendable { public var x, y, w, h: Int
        public func contains(_ px: Int, _ py: Int) -> Bool { px >= x && px < x + w && py >= y && py < y + h }
    }
    public var width: Int, height: Int, cell: Int
    /// The openings symbols show through: one per reel (and one per hot-reel cell row).
    public var windows: [Rect] = []
    /// The divider bars between them, a layer of their own.
    public var dividers: [Rect] = []
    /// The whole grid, main and hot reel together, that the reel texture fills.
    public var grid: Rect
    public var band: Int, gap: Int, radius: Int

    public static let bandShare = 0.20, gapShare = 0.045, bleedShare = 0.05, radiusShare = 0.1, crestRoom = 0.5, margin = 0.3

    /// The base grid (rows x reels) and a hot reel of `hot` rows above it when there is one, at `cell`
    /// pixels a cell; the canvas rounded up to multiples of 16, as GPT Image takes sizes.
    /// `independent`: every cell its own window, with dividers between rows too (hold-and-spin grids).
    public init(rows: Int, reels: Int, hotRows: Int = 0, independent: Bool = false, cell: Int = 512) {
        self.cell = cell
        let band = Int((Self.bandShare * Double(cell)).rounded()), gap = Int((Self.gapShare * Double(cell)).rounded())
        self.band = band; self.gap = gap; self.radius = Int((Self.radiusShare * Double(cell)).rounded())
        let gridW = reels * cell + (reels - 1) * gap
        let hotH = hotRows > 0 ? Int(Double(hotRows) * 0.85 * Double(cell)) : 0
        let mainH = rows * cell + (independent ? (rows - 1) * gap : 0)
        let gridH = mainH + (hotRows > 0 ? hotH + band : 0)
        let side = Int(Self.margin * Double(cell)), top = Int((Self.margin + Self.crestRoom) * Double(cell))
        func up16(_ v: Int) -> Int { (v + 15) / 16 * 16 }
        width = up16(gridW + 2 * band + 2 * side); height = up16(gridH + 2 * band + top + side)
        let gx = (width - gridW) / 2, gy = top + band + (height - (gridH + 2 * band + top + side)) / 2
        grid = Rect(x: gx, y: gy, w: gridW, h: gridH)
        var y = gy
        if hotRows > 0 {
            // The hot reel: one window per reel, the bar under it as wide as the band.
            for r in 0..<reels { windows.append(Rect(x: gx + r * (cell + gap), y: y, w: cell, h: hotH)) }
            for r in 1..<reels { dividers.append(Rect(x: gx + r * (cell + gap) - gap, y: y, w: gap, h: hotH)) }
            y += hotH + band
        }
        if independent {
            for row in 0..<rows { for r in 0..<reels { windows.append(Rect(x: gx + r * (cell + gap), y: y + row * (cell + gap), w: cell, h: cell)) } }
            for row in 1..<rows { dividers.append(Rect(x: gx, y: y + row * (cell + gap) - gap, w: gridW, h: gap)) }
        } else {
            for r in 0..<reels { windows.append(Rect(x: gx + r * (cell + gap), y: y, w: cell, h: mainH)) }
        }
        for r in 1..<reels { dividers.append(Rect(x: gx + r * (cell + gap) - gap, y: y, w: gap, h: mainH)) }
    }
    /// `grid`'s reel area, the base grid's by default; a hot reel above belongs to the base grid only.
    public init(_ layout: ReelLayout, grid: ReelLayout.Grid? = nil, cell: Int = 512) {
        let g = grid ?? layout.base ?? ReelLayout.Grid(mode: "base", rows: 3, reels: 5)
        // A hot reel, or any reel added above the base grid, sits in its housing on the top band.
        let hot = g == layout.base ? layout.hotReelAbove : nil
        self.init(rows: g.rows, reels: g.reels, hotRows: hot.map { $0.rows ?? 1 } ?? 0, independent: g.independent, cell: cell)
    }
    /// Where a pixel is: 0 outside the frame, 1 in the band (or the hot bar), 2 a divider, 3 an opening.
    func zone(_ x: Int, _ y: Int) -> Int {
        if windows.contains(where: { $0.contains(x, y) }) { return 3 }
        if dividers.contains(where: { $0.contains(x, y) }) { return 2 }
        let outer = Rect(x: grid.x - band, y: grid.y - band, w: grid.w + 2 * band, h: grid.h + 2 * band)
        guard outer.contains(x, y) else { return 0 }
        // rounded outer corners
        let r = Double(radius + band)
        let cx = Double(min(max(x, outer.x + Int(r)), outer.x + outer.w - Int(r))), cy = Double(min(max(y, outer.y + Int(r)), outer.y + outer.h - Int(r)))
        return (Double(x) - cx) * (Double(x) - cx) + (Double(y) - cy) * (Double(y) - cy) <= r * r ? 1 : 0
    }

    /// The grey moulding GPT Image repaints (opaque RGBA on the backing): the band shaded as a bevel lit
    /// from the top, the dividers as narrow bars, the openings the flat backing.
    func template(backing b: RGB8) -> [UInt8] {
        var px = [UInt8](repeating: 255, count: width * height * 4)
        let outer = Rect(x: grid.x - band, y: grid.y - band, w: grid.w + 2 * band, h: grid.h + 2 * band)
        for y in 0..<height { for x in 0..<width {
            let i = (y * width + x) * 4
            var v: (UInt8, UInt8, UInt8) = (b.r, b.g, b.b)
            switch zone(x, y) {
            case 1:
                // depth into the band from the outer edge, 0…1, and which way it faces
                let dl = x - outer.x, dr = outer.x + outer.w - 1 - x, dt = y - outer.y, db = outer.y + outer.h - 1 - y
                let d = min(dl, dr, dt, db), u = Double(d) / Double(max(1, band))
                let facingUp = d == dt ? 1.0 : d == db ? -1.0 : 0.3
                // Past the outer band — the bar under a hot reel — a flat face.
                let shade = u > 1.06 ? 150.0 : u < 0.06 || u > 0.94 ? 60.0 : u < 0.25 ? 150 + 70 * facingUp : u > 0.75 ? 125 - 60 * facingUp : 160 - 20 * abs(u - 0.5)
                let c = UInt8(max(0, min(255, shade))); v = (c, c, c)
            case 2:
                // A narrow bevelled bar: dark edges, lit across its middle — across its width or its height.
                let d = dividers.first { $0.contains(x, y) }
                let u = d.map { $0.w <= $0.h ? Double(x - $0.x) : Double(y - $0.y) }.map { $0 / Double(max(1, gap - 1)) } ?? 0.5
                let c = UInt8(max(0, min(255, u < 0.12 || u > 0.88 ? 85 : 170 - 60 * abs(u - 0.5)))); v = (c, c, c)
            default: break
            }
            px[i] = v.0; px[i + 1] = v.1; px[i + 2] = v.2; px[i + 3] = 255
        } }
        return px
    }

    /// The share of the openings a drawn bezel covers (opaque RGBA on its backing): the bezel's window
    /// check, as FrameStack.windowCovered is the symbol frames'.
    func covered(_ px: [UInt8], backing b: RGB8) -> Double {
        var open = 0, hit = 0
        for w in windows { for y in w.y..<(w.y + w.h) { for x in w.x..<(w.x + w.w) {
            let i = (y * width + x) * 4
            open += 1
            if abs(Int(px[i]) - Int(b.r)) + abs(Int(px[i + 1]) - Int(b.g)) + abs(Int(px[i + 2]) - Int(b.b)) > 90 { hit += 1 }
        } } }
        return open > 0 ? Double(hit) / Double(open) : 1
    }

    /// The bezel and dividers as layers of their own (straight RGBA), from the drawn bezel keyed off its
    /// backing: the dividers are their regions, the bezel everything else; both empty in the openings.
    func layers(_ keyed: [UInt8]) -> (bezel: [UInt8], dividers: [UInt8]) {
        var bezel = keyed, div = [UInt8](repeating: 0, count: keyed.count)
        for y in 0..<height { for x in 0..<width {
            let i = (y * width + x) * 4
            switch zone(x, y) {
            case 3: bezel[i + 3] = 0
            case 2: for c in 0..<4 { div[i + c] = keyed[i + c] }; bezel[i + 3] = 0
            default: break
            }
        } }
        return (bezel, div)
    }

    /// The reel texture laid in its place: the drawn texture fitted over the grid, running `bleedShare`
    /// under the band, its corners rounded; transparent elsewhere.
    func textureLayer(_ texture: [UInt8], width tw: Int, height th: Int) -> [UInt8] {
        let bleed = Int(Self.bleedShare * Double(cell))
        let r = Rect(x: grid.x - bleed, y: grid.y - bleed, w: grid.w + 2 * bleed, h: grid.h + 2 * bleed)
        var out = [UInt8](repeating: 0, count: width * height * 4)
        let rad = Double(radius)
        for y in r.y..<(r.y + r.h) { for x in r.x..<(r.x + r.w) {
            let cx = Double(min(max(x, r.x + radius), r.x + r.w - 1 - radius)), cy = Double(min(max(y, r.y + radius), r.y + r.h - 1 - radius))
            guard (Double(x) - cx) * (Double(x) - cx) + (Double(y) - cy) * (Double(y) - cy) <= rad * rad else { continue }
            let sx = min(tw - 1, (x - r.x) * tw / r.w), sy = min(th - 1, (y - r.y) * th / r.h)
            let s = (sy * tw + sx) * 4, d = (y * width + x) * 4
            out[d] = texture[s]; out[d + 1] = texture[s + 1]; out[d + 2] = texture[s + 2]; out[d + 3] = 255
        } }
        return out
    }

    /// The reel fade: flat black over the grid at `alpha`, the studio's reelFade.
    func fadeLayer(alpha: Double = 0.6) -> [UInt8] {
        var out = [UInt8](repeating: 0, count: width * height * 4)
        for y in grid.y..<(grid.y + grid.h) { for x in grid.x..<(grid.x + grid.w) { out[(y * width + x) * 4 + 3] = UInt8(alpha * 255) } }
        return out
    }
}

extension ReelArea {
    /// The outer edge of the band.
    var outer: Rect { Rect(x: grid.x - band, y: grid.y - band, w: grid.w + 2 * band, h: grid.h + 2 * band) }

    /// The base game's bezel and dividers re-laid round another grid of the same game, in code, as the
    /// studio re-lays one bezel's material for a new grid (Golden Knight's: corners, edge runs, side posts,
    /// a centred crest). Each edge is cut into its corners, its centre piece (the crest on top) and the two
    /// stretches between; a stretch is lengthened by repeating it mirrored an odd number of times and fitting
    /// that to the new length, so each end still meets the piece it met in the base — the band sweeps up to
    /// the crest, and a run cut from near the corners met it a step lower (Chevy-Hot, 2026-10-04). Dividers
    /// are a run of a base divider. Exact by construction, and free: GPT's own re-lay of a 3x4 grid shifted its
    /// rows into 16% of the openings. Straight RGBA in and out.
    static func relay(bezel: [UInt8], dividers: [UInt8], from a: ReelArea, to b: ReelArea) -> (bezel: [UInt8], dividers: [UInt8]) {
        let W = b.width, H = b.height, ao = a.outer, bo = b.outer
        var out = [UInt8](repeating: 0, count: W * H * 4), div = out
        let k = a.band + Int(0.35 * Double(a.cell))                       // a corner reaches this far along each edge
        let mx = ao.x, my = ao.y, mr = a.width - (ao.x + ao.w), mb = a.height - (ao.y + ao.h)
        let topH = my + k, botH = mb + k, leftW = mx + k, rightW = mr + k
        func crop(_ src: [UInt8], _ x: Int, _ y: Int, _ w: Int, _ h: Int) -> FrameKit.Piece { FrameKit.crop(src, width: a.width, max(0, x), max(0, y), max(1, w), max(1, h)) }
        func paste(_ p: FrameKit.Piece, _ x: Int, _ y: Int, into dst: inout [UInt8]) { FrameKit.over(&dst, width: W, p, at: x, y) }
        /// `p` lengthened (or shortened) to `length` along its edge: repeated mirrored an odd number of times,
        /// so it starts and ends as it did, then fitted to the length.
        func span(_ p: FrameKit.Piece, _ length: Int, horizontal: Bool) -> FrameKit.Piece {
            guard length > 0 else { return FrameKit.Piece(px: [0, 0, 0, 0], w: 1, h: 1) }
            let unit = horizontal ? p.w : p.h
            var n = max(1, Int((Double(length) / Double(max(1, unit))).rounded())); if n % 2 == 0 { n += 1 }
            let w = horizontal ? unit * n : p.w, h = horizontal ? p.h : unit * n
            var px = [UInt8](repeating: 0, count: w * h * 4)
            for j in 0..<n {
                let q = j % 2 == 0 ? p : FrameKit.flipped(p, x: horizontal, y: !horizontal)
                for yy in 0..<q.h { for xx in 0..<q.w {
                    let X = horizontal ? j * unit + xx : xx, Y = horizontal ? yy : j * unit + yy
                    for c in 0..<4 { px[(Y * w + X) * 4 + c] = q.px[(yy * q.w + xx) * 4 + c] }
                } }
            }
            return FrameKit.resized(FrameKit.Piece(px: px, w: w, h: h), horizontal ? length : w, horizontal ? h : length)
        }
        // Top and bottom: corner | stretch | centre piece | stretch | corner, the centre at the middle of the edge.
        let cw = min(Int(1.3 * Double(a.cell)), ao.w / 3)
        let aL = ao.x + k, aC = ao.x + (ao.w - cw) / 2, aR = ao.x + ao.w - k
        let bL = bo.x + k, bC = bo.x + (bo.w - cw) / 2, bR = bo.x + bo.w - k
        for (y0, h, ny) in [(0, topH, bo.y - my), (ao.y + ao.h - k, botH, bo.y + bo.h - k)] {
            paste(span(crop(bezel, aL, y0, aC - aL, h), bC - bL, horizontal: true), bL, ny, into: &out)
            paste(span(crop(bezel, aC + cw, y0, aR - aC - cw, h), bR - bC - cw, horizontal: true), bC + cw, ny, into: &out)
            paste(crop(bezel, aC, y0, cw, h), bC, ny, into: &out)
        }
        // Sides: corner | stretch | post | stretch | corner. Both stretches come from below the post: above it a
        // base with a hot reel has the bar joining its side, which a grid without one must not carry.
        let ch = min(Int(0.9 * Double(a.cell)), ao.h / 3)
        let sideY = a.windows.last.map { $0.y + $0.h / 2 } ?? (ao.y + ao.h / 2)
        let aP = sideY - ch / 2, aB = ao.y + ao.h - k
        let bT = bo.y + k, bP = bo.y + (bo.h - ch) / 2, bB = bo.y + bo.h - k
        for (x0, w, nx) in [(0, leftW, bo.x - mx), (ao.x + ao.w - k, rightW, bo.x + bo.w - k)] {
            let lower = crop(bezel, x0, aP + ch, w, aB - aP - ch)
            paste(span(FrameKit.flipped(lower, x: false, y: true), bP - bT, horizontal: false), nx, bT, into: &out)
            paste(span(lower, bB - bP - ch, horizontal: false), nx, bP + ch, into: &out)
            paste(crop(bezel, x0, aP, w, ch), nx, bP, into: &out)
        }
        // Corners.
        paste(crop(bezel, 0, 0, leftW, topH), bo.x - mx, bo.y - my, into: &out)
        paste(crop(bezel, ao.x + ao.w - k, 0, rightW, topH), bo.x + bo.w - k, bo.y - my, into: &out)
        paste(crop(bezel, 0, ao.y + ao.h - k, leftW, botH), bo.x - mx, bo.y + bo.h - k, into: &out)
        paste(crop(bezel, ao.x + ao.w - k, ao.y + ao.h - k, rightW, botH), bo.x + bo.w - k, bo.y + bo.h - k, into: &out)
        // Dividers: a stretch of the base's last divider, the length of each new one; across, the same turned.
        if let d = a.dividers.last(where: { $0.h > $0.w }) {
            let seg = crop(dividers, d.x, d.y + d.h / 4, d.w, max(16, d.h / 2))
            for nd in b.dividers {
                let across = nd.w > nd.h
                paste(span(across ? FrameKit.turned(seg, degrees: 90) : seg, across ? nd.w : nd.h, horizontal: across), nd.x, nd.y, into: &div)
            }
        }
        // Nothing of either in the openings.
        for w in b.windows { for y in w.y..<(w.y + w.h) { for x in w.x..<(w.x + w.w) { out[(y * W + x) * 4 + 3] = 0; div[(y * W + x) * 4 + 3] = 0 } } }
        return (out, div)
    }
}

/// The jackpot table that sits above the reels: a plate as wide as the bezel with one plaque per jackpot,
/// each its name lettered over an empty value field the game prints the amount in. Laid out in code, like
/// the bezel, for GPT Image to paint.
/// A pot's filling and full states laid on its empty pot. GPT Image redraws the whole pot for a state, a few
/// percent bigger or smaller and shifted (Toyota, 2026-10-04: full pots 8–12% narrower at the foot), so a
/// state swap in game would jump. The foot is what filling leaves alone: each state is scaled to the empty
/// pot's foot width and set on its foot's bottom centre. Every pot file has `headroom` clear above the pot,
/// room for what rises from it when full (square, GPT filled the canvas and the treasure was cut flat).
/// What a game's pot is, and so how it shows that it fills. Every shipped rig (18 exports, research/pots.md) is a fixed
/// body, a lid or door that opens a little more each state, and treasure that rises until it overflows — or, with no
/// opening, treasure piling up round it. The rig is `shared_avatar_jar` whatever the object.
public enum PotKind: String, Codable, CaseIterable, Sendable {
    /// A pot, jar, urn, cauldron or drum: its lid lifted by the treasure (88 Drums, Cauldron Cash; the lid its own part).
    case jar
    /// A chest, coffer or casket: its lid swinging open on its hinge in steps (Da Vinci 77: about 74° to fully open over
    /// five states; Jewel of Alexandria), the treasure rising and spilling over its front.
    case chest
    /// A safe, vault or strongbox: its door swinging open in steps, gold stacked inside (Bankrush's safe).
    case safe
    /// A piggy bank, or any closed figure with no lid: the treasure piling up round its base and behind it (the Blitz
    /// vault medallion's pile grows sideways round its base, to about 2.6 times its width).
    case piggyBank
    public var noun: String { switch self { case .jar: "pot"; case .chest: "treasure chest"; case .safe: "safe"; case .piggyBank: "piggy bank" } }
    public var nouns: String { switch self { case .jar: "pots"; case .chest: "treasure chests"; case .safe: "safes"; case .piggyBank: "piggy banks" } }
    /// The part of it that stays put and in view as it fills, to lay each state on State0 by: a jar's and a chest's lids
    /// rise, so their foot; a safe's gold pours out over its sill, so its top; a piggy bank's coins pile round and behind
    /// it up to its ears, so its face (laid by its foot, it shrank to a third as its pile widened; by its top, as the
    /// pile behind it reached its ears, 2026-10-05).
    public enum Anchor: Sendable { case foot, top, face }
    public var anchor: Anchor { switch self { case .jar, .chest: .foot; case .safe: .top; case .piggyBank: .face } }
    /// The most of its canvas's width it stands in at State0: a piggy bank's coins pile up beside it (the Blitz
    /// medallion's pile reached 2.6 times its width), so it stands narrow; the others may fill it.
    public var bodyShare: Double { self == .piggyBank ? 0.45 : 1 }
    /// The room it leaves under its foot at State0, in its canvas's heights: a safe's gold and a piggy bank's coins pile on
    /// the floor in front of it, lower than its foot (a safe's State5 pour ran off the canvas's bottom, 2026-10-05).
    public var footRoom: Double { anchor == .foot ? 0 : 0.08 }
    /// The most of its State0's face a drawn state may have changed by (PotStates.changedShare): a safe's State1 is a door
    /// open a crack — drawn freely it stood a quarter open, full of gold (0.26); held to its stage it measured 0.19. Later states
    /// are not capped by it: a door swung open on a dark inside changes as much as gold filling it (the good safe measured
    /// 0.30, 0.34, 0.36 against the overshooting one's 0.29, 0.31, 0.36, 2026-10-05) — Gemini judges those. Nil: no cap.
    public func revealCap(_ k: Int) -> Double? { self == .safe && k == 1 ? 0.22 : nil }
    /// Its State0: closed, empty, unlit.
    var closed: String {
        switch self {
        case .jar: "empty and unlit — its lid closed if it has one, its mouth open and empty if not"
        case .chest: "closed and unlit: its lid shut on its hinge, nothing of its treasure showing"
        case .safe: "closed and unlit: its door shut and locked, nothing of its treasure showing"
        case .piggyBank: "unlit, nothing round it: a sturdy piggy bank with a coin slot in its back"
        }
    }
    /// How far it has opened at each state, 1…5 (the jar's lid is laid in code; this is its words when it is not).
    func opening(_ k: Int) -> String {
        let i = min(max(k, 1), 5) - 1
        switch self {
        case .jar: return ["its lid lifted just off its rim", "its lid lifted a little and tipped back", "its lid tipped further back", "its lid swung open", "its lid thrown open"][i]
        case .chest: return ["its lid open just a crack on its hinge, about 15°", "its lid open about 30°", "its lid open about halfway, 45°", "its lid open about 60°", "its lid thrown fully open on its hinge, 75° or more"][i]
        case .safe: return ["its door unlatched and open just a crack — a narrow dark gap down its edge, the door still covering almost all of the opening",
                            "its door open about a quarter", "its door open about halfway", "its door open most of the way", "its door swung wide open"][i]
        case .piggyBank: return ["", "", "", "", ""][i]
        }
    }
    /// Where its treasure is at each state, 1…5.
    func treasure(_ k: Int) -> String {
        let i = min(max(k, 1), 5) - 1
        switch self {
        case .jar, .chest: return ["the first of its treasure glinting inside", "its treasure showing at the rim", "its treasure heaped level with the rim",
                                   "its treasure heaped above the rim, beginning to spill over the front", "full to overflowing: treasure pouring over the rim and down its front and sides"][i]
        case .safe: return ["only a glint of gold in that narrow gap", "the first gold bars and coins on its lowest shelf, the rest of it still dark", "gold stacked halfway up inside",
                            "gold stacked to the top inside, a few coins spilling out over the sill", "full to overflowing: gold pouring out of the door and piling in front of it"][i]
        case .piggyBank: return ["a few coins scattered at its feet", "a small pile of coins round its feet", "coins piled round it up to its belly",
                                 "coins piled round and behind it up to its back, its face and ears in full view", "full to overflowing: a great pile of coins round and behind it, spilling wide to both sides, its face and ears in full view above them"][i]
        }
    }
    /// The kind a text names: the first vessel word in it.
    public static func read(_ text: String) -> PotKind? {
        let l = text.lowercased()
        let words: [(String, PotKind)] = [(#"\bpiggy[ -]?banks?\b|\bpiggies\b|\bpiggy\b"#, .piggyBank), (#"\b(safes?|vaults?|strongbox(es)?|strong box(es)?)\b"#, .safe),
                                          (#"\b(chests?|coffers?|caskets?|treasure box(es)?)\b"#, .chest),
                                          (#"\b(pots?|jars?|urns?|cauldrons?|drums?|vases?|pumpkins?|chalices?|amphoras?)\b"#, .jar)]
        return words.compactMap { (re, k) in l.range(of: re, options: .regularExpression).map { ($0.lowerBound, k) } }.min { $0.0 < $1.0 }?.1
    }
}

public enum PotStates {
    /// Room above the pot, in its width: half — a lid thrown open early (GPT, 2026-10-04: 16% of the pot's height at
    /// State1) still leaves the later states room to keep rising; 1024x1536 is a size GPT Image draws natively.
    public static let headroom = 0.5
    /// The studio's pot rig (`shared_avatar_jar`, 18 rigs in about 17 shipped games, 2026-10-04): State0 empty
    /// and unlit, then five fill states — a lid opening further each time, the game's treasure rising until it
    /// overflows at State5, the glow growing. The pot itself never moves. A burst and reset are the rig's own.
    public static let levels = 5
    /// What each of `count` pots unlocks, from a sentence that lists them after a colon, as plaque words —
    /// the short words the studio letters on them (Toyota's mock-up: EXPAND / MULTI / JACKPOTS OR WILDS).
    public static func features(_ gdd: String, count: Int) -> [String]? {
        for line in gdd.components(separatedBy: .newlines) {
            let l = line.lowercased()
            guard l.range(of: #"\bpots?\b"#, options: .regularExpression) != nil, let colon = l.firstIndex(of: ":") else { continue }
            let list = l[l.index(after: colon)...].components(separatedBy: ".").first ?? ""
            let items = list.components(separatedBy: ",").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
            guard items.count == count else { continue }
            return items.map { i in
                let wild = i.range(of: #"\bwild|\bwdwy|\bwd\d"#, options: .regularExpression) != nil, jackpot = i.contains("jackpot")
                if wild && jackpot { return "JACKPOTS OR WILDS" }
                if jackpot { return "JACKPOTS" }
                if wild { return "WILDS" }
                if i.contains("multiplier") { return "MULTI" }
                if i.contains("respin") { return "RESPINS" }
                if i.contains("collect") { return "COLLECT" }
                if i.range(of: #"matrix|expand|grow|extra (row|reel)"#, options: .regularExpression) != nil { return "EXPAND" }
                if i.range(of: #"bonus game|free (game|spin)"#, options: .regularExpression) != nil { return "BONUS GAMES" }
                // Already a plaque's word or two ("multi"): as written.
                let words = i.replacingOccurrences(of: #"^(and|or)\s+"#, with: "", options: .regularExpression)
                return words.split(separator: " ").count <= 3 ? Wording.noFree(words).uppercased() : ""
            }
        }
        return nil
    }
    /// A pot's plaque, beneath it, when a game has several: `shared_avatar_jar2-plaque`.
    public static func plaqueName(pot i: Int) -> String { "shared_avatar_jar\(i + 1)-plaque" }
    /// A pot state's file name, the rig's: `shared_avatar_jar-State3Idle`, numbered when a game has several pots.
    public static func name(pot i: Int, of total: Int, state k: Int) -> String {
        "shared_avatar_jar\(total > 1 ? "\(i + 1)" : "")-State\(k)Idle"
    }
    /// How far each state's top stands above State0's, in State0's heights: the mean of the shipped rigs (88 Drums'
    /// jar 0-2-4-13-23-29%, Jewel of Alexandria's chest 0-5-8-13-18-27%, Cauldron Cash's pumpkin 0-1-8-14-18-23%;
    /// research/legibility-measure.md §6). Back-loaded, so the last states still grow: generated rigs drawn each from
    /// State0 reached 91–99% of their height by State3 and barely changed after it.
    public static let rise = [0.0, 0.03, 0.07, 0.13, 0.20, 0.26]
    /// The rows a silhouette spans: those with an opaque pixel in at least 1% of the width.
    static func span(_ px: [UInt8], width w: Int, height h: Int) -> (top: Int, bottom: Int)? {
        let rows = (0..<h).filter { y in (0..<w).reduce(0) { $0 + (px[(y * w + $1) * 4 + 3] > 128 ? 1 : 0) } >= max(1, w / 100) }
        return rows.first.map { ($0, rows.last!) }
    }
    /// A pot's lid as its own part, as the studio's rigs carry it (Cauldron Cash's `pupmkin_lid`): drawn once from State0
    /// and laid on each state's treasure in code, tipped further open as it fills — GPT, asked to keep a lid while showing
    /// the treasure, took it away and every state after it grew without one (2026-10-05).
    public static func lidName(pot i: Int, of total: Int) -> String { "shared_avatar_jar\(total > 1 ? "\(i + 1)" : "")-lid" }
    /// How far the lid is tipped at each state, in degrees.
    /// Gentle: a lid lifted by the treasure under it stays nearly level (a flat lid spun 30° read as sliding off, 2026-10-05).
    public static let lidTilt: [Double] = [0, 2, 3, 5, 6, 8]
    static func box(_ px: [UInt8], width w: Int, height h: Int) -> (x: Int, y: Int, w: Int, h: Int)? {
        var x0 = w, y0 = h, x1 = -1, y1 = -1
        for y in 0..<h { for x in 0..<w where px[(y * w + x) * 4 + 3] > 128 { x0 = min(x0, x); x1 = max(x1, x); y0 = min(y0, y); y1 = max(y1, y) } }
        return x1 < 0 ? nil : (x0, y0, x1 - x0 + 1, y1 - y0 + 1)
    }
    /// State0 with its lid taken off (GPT, laid on State0's foot), so its open mouth shows.
    public static func openName(pot i: Int, of total: Int) -> String { name(pot: i, of: total, state: 0) + "_open" }
    /// The pot heaped full (GPT), its treasure's one drawing; and the parts cut from it for the animators.
    public static func fullName(pot i: Int, of total: Int) -> String { name(pot: i, of: total, state: 0) + "_full" }
    public static func partName(_ part: String, pot i: Int, of total: Int) -> String { "shared_avatar_jar\(total > 1 ? "\(i + 1)" : "")-\(part)" }
    /// The lid, as State0's own pixels — exactly the lid, in exactly its place (asked to draw the lid alone, GPT drew it larger
    /// and centred, 2026-10-05): State0 above the open pot's rim line (its first row 40% as wide as its widest, a little below
    /// for the lid's brim), wherever the open pot is not there or differs from it; its largest connected piece, so a handle's
    /// tip GPT nudged is no part of it. Nil when that is no whole lid: in pieces, or under 4% or over 45% of the pot's height.
    public static func lidFrom(empty: [UInt8], open: [UInt8], width w: Int, height h: Int) -> [UInt8]? {
        guard let e = box(empty, width: w, height: h), let o = box(open, width: w, height: h) else { return nil }
        func width(_ px: [UInt8], _ y: Int) -> Int { let xs = (0..<w).filter { px[(y * w + $0) * 4 + 3] > 128 }; return xs.isEmpty ? 0 : xs.last! - xs.first! }
        let widest = (o.y..<(o.y + o.h)).map { width(open, $0) }.max() ?? 0
        guard let rim = (o.y..<(o.y + o.h)).first(where: { Double(width(open, $0)) >= 0.4 * Double(widest) }) else { return nil }
        let band = rim + Int(0.04 * Double(e.h))
        var mask = [Bool](repeating: false, count: w * h)
        for y in 0..<min(h, band) { for x in 0..<w {
            let i = (y * w + x) * 4
            guard empty[i + 3] > 128 else { continue }
            let diff = abs(Int(empty[i]) - Int(open[i])) + abs(Int(empty[i + 1]) - Int(open[i + 1])) + abs(Int(empty[i + 2]) - Int(open[i + 2]))
            if open[i + 3] <= 128 || diff > 45 { mask[y * w + x] = true }
        } }
        // Its largest connected piece.
        var label = [Int](repeating: 0, count: w * h), sizes: [Int] = [0], next = 1
        for start in 0..<(w * h) where mask[start] && label[start] == 0 {
            var stack = [start], n = 0
            label[start] = next
            while let i = stack.popLast() {
                n += 1
                let x = i % w, y = i / w
                for (nx, ny) in [(x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)] where nx >= 0 && nx < w && ny >= 0 && ny < h {
                    let j = ny * w + nx
                    if mask[j] && label[j] == 0 { label[j] = next; stack.append(j) }
                }
            }
            sizes.append(n); next += 1
        }
        guard let biggest = sizes.indices.dropFirst().max(by: { sizes[$0] < sizes[$1] }) else { return nil }
        var lid = [UInt8](repeating: 0, count: w * h * 4)
        for i in 0..<(w * h) where label[i] == biggest { for c in 0..<4 { lid[i * 4 + c] = empty[i * 4 + c] } }
        guard let l = box(lid, width: w, height: h), Double(l.h) >= 0.04 * Double(e.h), Double(l.h) <= 0.45 * Double(e.h),
              Double(sizes[biggest]) >= 0.7 * Double(sizes.dropFirst().reduce(0, +)) else { return nil }
        return lid
    }
    /// State0 without its lid: its pixels where the lid is not.
    public static func withoutLid(_ empty: [UInt8], lid: [UInt8]) -> [UInt8] {
        var out = empty
        for i in 0..<(empty.count / 4) where lid[i * 4 + 3] > 128 { out[i * 4 + 3] = 0 }
        return out
    }
    /// The lid laid on a state's template (straight RGBA: its body and grey heap): tipped `lidTilt[k]` degrees and dropped until
    /// it rests on what is under it, settled into it a sixteenth of its height — at stage 1 then lifted just off its rim, by
    /// 3% of the pot's height, for the first treasure to glint in the gap. Returns the template with the lid on, and the lid
    /// as laid (its own layer, for the next state and for the animators).
    public static func placeLid(on px: [UInt8], lid: [UInt8], width w: Int, height h: Int, state k: Int) -> (px: [UInt8], lid: [UInt8])? {
        guard let l = box(lid, width: w, height: h), let b = box(px, width: w, height: h) else { return nil }
        let tilt = lidTilt[min(k, lidTilt.count - 1)], a = -tilt * .pi / 180
        let piece = FrameKit.crop(lid, width: w, l.x, l.y, l.w, l.h)
        let space = CGColorSpace(name: CGColorSpace.sRGB)!
        let cx = Double(l.x) + Double(l.w) / 2 + Double(l.w) * tilt / 300, cy = Double(l.y) + Double(l.h) / 2
        guard let img = ChromaKeyOutputRules.image(straightRGBA8: piece.px, width: piece.w, height: piece.h, space: space),
              let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0, space: space,
                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        ctx.interpolationQuality = .high
        ctx.translateBy(x: cx, y: Double(h) - cy)                 // CG's y runs up
        ctx.rotate(by: -a)
        ctx.draw(img, in: CGRect(x: -Double(l.w) / 2, y: -Double(l.h) / 2, width: Double(l.w), height: Double(l.h)))
        guard let laidImg = ctx.makeImage(), let lidPx = ChromaKeyOutputRules.straightRGBA8(laidImg) else { return nil }
        // Dropped until its underside meets what is under it in some column, settled a little into it.
        var dy = Int.max
        let sink = max(2, l.h / 16)
        for x in 0..<w {
            var lidBottom = -1, top = h
            for y in 0..<h { if lidPx[(y * w + x) * 4 + 3] > 128 { lidBottom = y } }
            guard lidBottom >= 0 else { continue }
            for y in 0..<h where px[(y * w + x) * 4 + 3] > 128 { top = y; break }
            guard top < h else { continue }
            dy = min(dy, top + sink - lidBottom)
        }
        guard dy != Int.max else { return nil }
        if k == 1 { dy -= Int(0.03 * Double(b.h)) }
        var laid = [UInt8](repeating: 0, count: w * h * 4)
        FrameKit.over(&laid, width: w, FrameKit.Piece(px: lidPx, w: w, h: h), at: 0, dy)
        var out = px
        FrameKit.over(&out, width: w, FrameKit.Piece(px: laid, w: w, h: h), at: 0, 0)
        return (out, laid)
    }
    /// How much of a cut-out is holes — transparent pixels it encloses, the backing showing through where the drawing left
    /// it (a magenta smudge in a pot's treasure, 2026-10-05) — as a share of its opaque pixels.
    public static func holeShare(_ px: [UInt8], width w: Int, height h: Int, besides reference: [UInt8]? = nil) -> Double {
        let mine = holes(px, width: w, height: h), theirs = reference.map { holes($0, width: w, height: h) }
        var n = 0, solid = 0
        for i in 0..<(w * h) { if px[i * 4 + 3] >= 128 { solid += 1 } else if mine[i] && !(theirs?[i] ?? false) { n += 1 } }
        return Double(n) / Double(max(1, solid))
    }
    /// The transparent pixels a cut-out encloses (not reached from the picture's border).
    static func holes(_ px: [UInt8], width w: Int, height h: Int) -> [Bool] {
        var outside = [Bool](repeating: false, count: w * h), stack: [Int] = []
        for x in 0..<w { stack.append(x); stack.append((h - 1) * w + x) }
        for y in 0..<h { stack.append(y * w); stack.append(y * w + w - 1) }
        while let i = stack.popLast() {
            guard !outside[i], px[i * 4 + 3] < 128 else { continue }
            outside[i] = true
            let x = i % w, y = i / w
            if x > 0 { stack.append(i - 1) }; if x < w - 1 { stack.append(i + 1) }
            if y > 0 { stack.append(i - w) }; if y < h - 1 { stack.append(i + w) }
        }
        return (0..<(w * h)).map { px[$0 * 4 + 3] < 128 && !outside[$0] }
    }
    /// A pot's Power Bet look, beside its states.
    public static func boostedName(pot i: Int, of total: Int) -> String { "shared_avatar_jar\(total > 1 ? "\(i + 1)" : "")-boostedIdle" }
    /// How the pots look with the Power Bet on, in the GDD's own sentence — only one that gives them a look of
    /// their own, in a Power Bet passage ("The pot turns gold, with valuable gold coins appearing behind it",
    /// Chevy). Their final state (Bankrush's safe: State5, drawn already) or an animation (88 Drums' "fancier
    /// idle") is no new picture: nil.
    public static func boost(_ gdd: String) -> String? {
        var sincePowerBet = 99
        for line in gdd.components(separatedBy: .newlines) {
            let l = line.lowercased()
            guard !l.trimmingCharacters(in: .whitespaces).isEmpty else { continue }
            sincePowerBet = l.range(of: #"power ?bets?|\bboost"#, options: .regularExpression) != nil ? 0 : min(sincePowerBet, 99) + 1
            guard sincePowerBet <= 12 else { continue }
            for sentence in line.components(separatedBy: ". ") {
                let t = sentence.lowercased()
                guard t.range(of: #"\b(pots?|jars?|safe|cauldron)\b[^.]{0,40}\b(turns?|becomes?|changes?|glows?)\b"#, options: .regularExpression) != nil,
                      !t.contains("state"), !t.contains("animation") else { continue }    // its states (Bankrush's "final state"): drawn already
                let clean = sentence.trimmingCharacters(in: CharacterSet(charactersIn: "*-•· \t")).trimmingCharacters(in: CharacterSet(charactersIn: "."))
                return Wording.noFree(clean) + "."
            }
        }
        return nil
    }
    /// The canvas height of a pot `n` wide: 1280 for 1024, a multiple of 16 as GPT Image takes sizes.
    public static func height(_ n: Int) -> Int { n + Int(headroom * Double(n)) / 16 * 16 }
    /// A pot drawn square (straight RGBA, `n` a side) stood at the bottom of its taller canvas.
    public static func padded(_ px: [UInt8], size n: Int) -> [UInt8] {
        [UInt8](repeating: 0, count: (height(n) - n) * n * 4) + px
    }

    /// The foot of a cut-out pot (straight RGBA, `w` by `h`): its bottom row, and the centre and width of the
    /// band just above it — or, `top`, its top row and the band just below it. Rows with only a few opaque pixels
    /// (strays at the edge) are not its end.
    static func foot(_ keyed: [UInt8], width w: Int, height h: Int, top: Bool = false) -> (cx: Double, end: Int, width: Double)? {
        func opaque(_ x: Int, _ y: Int) -> Bool { keyed[(y * w + x) * 4 + 3] > 128 }
        let rows = top ? Array(0..<h) : (0..<h).reversed()
        guard let end = rows.first(where: { y in (0..<w).filter { opaque($0, y) }.count >= w / 50 }) else { return nil }
        let near = Int(0.03 * Double(w)), far = Int(0.08 * Double(w))
        let band = top ? min(h - 1, end + near)..<min(h, end + far) : max(0, end - far)..<max(1, end - near)
        let cols = (0..<w).filter { x in band.contains { opaque(x, $0) } }
        guard let a = cols.first, let b = cols.last else { return nil }
        return (Double(a + b) / 2, end, Double(b - a))
    }

    /// A pot made to stand as its kind needs (PotKind.bodyShare, footRoom): no wider than `share` of its canvas, centred,
    /// and its foot `room` of the canvas's height above its bottom; nil when it stands so already.
    public static func stood(_ px: [UInt8], width w: Int, height h: Int, share: Double, room: Double) -> [UInt8]? {
        guard let f = foot(px, width: w, height: h) else { return nil }
        let cols = (0..<w).filter { x in (0..<h).reduce(0) { $0 + (px[($1 * w + x) * 4 + 3] > 128 ? 1 : 0) } >= max(1, h / 100) }
        guard let a = cols.first, let b = cols.last else { return nil }
        let k = min(1, share * Double(w) / Double(max(1, b - a))), end = min(Double(f.end), Double(h - 1) - room * Double(h))
        guard k < 0.99 || Double(f.end) - end > 2 else { return nil }
        let scaled = FrameKit.resized(FrameKit.Piece(px: px, w: w, h: h), Int((Double(w) * k).rounded()), Int((Double(h) * k).rounded()))
        var out = [UInt8](repeating: 0, count: w * h * 4)
        FrameKit.over(&out, width: w, scaled, at: k < 0.99 ? Int((Double(w) / 2 - Double(a + b) / 2 * k).rounded()) : 0, Int((end - Double(f.end) * k).rounded()))
        return out
    }
    /// Whether a state runs off its canvas: more than a speck of it on the bottom row or a side column.
    public static func cutOff(_ px: [UInt8], width w: Int, height h: Int) -> Bool {
        (0..<w).filter { px[((h - 1) * w + $0) * 4 + 3] > 128 }.count > w / 50
            || (0..<h).filter { px[$0 * w * 4 + 3] > 128 || px[($0 * w + w - 1) * 4 + 3] > 128 }.count > h / 50
    }

    /// `state` laid on `empty` by the part of it that stays put as it fills (PotKind.anchor).
    public static func laid(_ state: [UInt8], on empty: [UInt8], width w: Int, height h: Int, by anchor: PotKind.Anchor) -> [UInt8] {
        anchor == .face ? matched(state, to: empty, width: w, height: h) : registered(state, to: empty, width: w, height: h, top: anchor == .top)
    }
    /// `state` laid on `empty` by `empty`'s own pixels in a band of its body's `rows` (its top half: a face, which stays in view): the
    /// scale and place that match them best, searched coarse to fine; left alone when it is in place already.
    public static func matched(_ state: [UInt8], to empty: [UInt8], width w: Int, height h: Int, rows: ClosedRange<Double> = 0...0.5) -> [UInt8] {
        guard let s0 = span(empty, width: w, height: h) else { return state }
        let yMin = s0.top + Int(Double(s0.bottom - s0.top) * rows.lowerBound), yMax = s0.top + Int(Double(s0.bottom - s0.top) * rows.upperBound)
        func points(_ step: Int) -> [(x: Double, y: Double, rgb: (Int, Int, Int))] {
            stride(from: yMin, to: yMax, by: step).flatMap { y in stride(from: 0, to: w, by: step).compactMap { x -> (x: Double, y: Double, rgb: (Int, Int, Int))? in
                let i = (y * w + x) * 4
                return empty[i + 3] > 200 ? (Double(x), Double(y), (Int(empty[i]), Int(empty[i + 1]), Int(empty[i + 2]))) : nil
            } }
        }
        // Where an empty pixel at p lands in the drawn state when the state is scaled by k and set at (ox, oy).
        func cost(_ k: Double, _ ox: Double, _ oy: Double, _ pts: [(x: Double, y: Double, rgb: (Int, Int, Int))]) -> Double {
            var sum = 0
            for p in pts {
                let x = Int(((p.x - ox) / k).rounded()), y = Int(((p.y - oy) / k).rounded())
                guard x >= 0, y >= 0, x < w, y < h else { sum += 765; continue }
                let i = (y * w + x) * 4
                sum += state[i + 3] < 128 ? 765 : abs(Int(state[i]) - p.rgb.0) + abs(Int(state[i + 1]) - p.rgb.1) + abs(Int(state[i + 2]) - p.rgb.2)
            }
            return Double(sum) / Double(max(1, pts.count))
        }
        // Scaled about the face's top centre, so a scale alone does not move it.
        let cx = Double(w) / 2, cy = Double(s0.top)
        func search(_ ks: [Double], _ ds: [Double], around: (k: Double, dx: Double, dy: Double), _ pts: [(x: Double, y: Double, rgb: (Int, Int, Int))]) -> (k: Double, dx: Double, dy: Double) {
            var best = (k: around.k, dx: around.dx, dy: around.dy), low = cost(around.k, cx * (1 - around.k) + around.dx, cy * (1 - around.k) + around.dy, pts)
            for k in ks { for dx in ds { for dy in ds {
                let c = cost(k, cx * (1 - k) + dx, cy * (1 - k) + dy, pts)
                if c < low - 0.01 { low = c; best = (k, dx, dy) }
            } } }
            return best
        }
        let coarse = search((-12...15).map { 1 + 0.02 * Double($0) }, stride(from: -64.0, through: 64, by: 8).map { $0 }, around: (1, 0, 0), points(16))
        let fine = search((-4...4).map { coarse.k + 0.005 * Double($0) }, (-8...8).map { Double($0) }, around: coarse, points(4))
        let k = fine.k, ox = cx * (1 - k) + fine.dx, oy = cy * (1 - k) + fine.dy
        // Already in place (to a pixel or two of resampling): left alone, so laying again never blurs it.
        guard abs(k - 1) > 0.004 || abs(ox) >= 2 || abs(oy) >= 2 else { return state }
        let scaled = FrameKit.resized(FrameKit.Piece(px: state, w: w, h: h), Int((Double(w) * k).rounded()), Int((Double(h) * k).rounded()))
        var out = [UInt8](repeating: 0, count: w * h * 4)
        FrameKit.over(&out, width: w, scaled, at: Int(ox.rounded()), Int(oy.rounded()))
        return out
    }
    /// A pot's parts, cut from three drawings as the studio's rigs hold them (research/pots.md: 18 rigs, body, lid and
    /// treasure as separate pieces): its body, never redrawn; its lid; its treasure — one heap that rises out of its mouth —
    /// and the treasure in front of it, which spills only in the last states. A pile round a base (the Blitz vault, a piggy
    /// bank) is drawn per state instead, as that rig's pile sprites are: sunk into its floor, a pile was sliced flat.
    public struct Parts {
        public var body: [UInt8]           // State0 without its lid; under the lid, the open pot's mouth
        public var lid: [UInt8]?           // State0's own lid pixels, in place
        public var heap: [UInt8]           // behind the front lip
        public var front: [UInt8]          // in front of the body: the spill over its lip
        public var lip: [Int]              // per column, the row the heap goes in behind the front lip
        public var rise: Int               // how far the drawn heap stands above where the lid rests, in px
        public let width: Int, height: Int
    }
    /// How much of the drawn heap shows at each state, 0…1, by the rigs' rise (88 Drums, Jewel of Alexandria, Cauldron
    /// Cash: hidden, a glint, peeking, mounded, high, overflowing).
    public static func shown(_ k: Int) -> Double { rise[min(max(k, 0), 5)] / rise[levels] }
    /// The treasure in `full`, the same pot drawn heaped (laid on `base` already): its pixels that differ from `base`,
    /// cleared of the hairlines and specks a redraw leaves on an unchanged body — whole pieces only.
    static func treasure(_ full: [UInt8], base: [UInt8], width w: Int, height h: Int, whole: Bool = true) -> [Bool] {
        var m = [Bool](repeating: false, count: w * h)
        for i in 0..<(w * h) where full[i * 4 + 3] > 128 {
            let d = abs(Int(full[i * 4]) - Int(base[i * 4])) + abs(Int(full[i * 4 + 1]) - Int(base[i * 4 + 1])) + abs(Int(full[i * 4 + 2]) - Int(base[i * 4 + 2]))
            m[i] = base[i * 4 + 3] <= 128 || d > 90
        }
        func step(_ m: [Bool], keep: Bool) -> [Bool] {      // erode (keep = all neighbours set) or dilate (any)
            var o = m
            for y in 1..<(h - 1) { for x in 1..<(w - 1) {
                let i = y * w + x, n = [m[i - 1], m[i + 1], m[i - w], m[i + w]]
                o[i] = keep ? (m[i] && !n.contains(false)) : (m[i] || n.contains(true))
            } }
            return o
        }
        // Opened twice (hairlines go), closed twice (the gaps between pieces fill), then specks under 0.05% of the canvas dropped.
        m = step(step(step(step(m, keep: true), keep: true), keep: false), keep: false)
        m = step(step(step(step(m, keep: false), keep: false), keep: true), keep: true)
        var label = [Int](repeating: 0, count: w * h), sizes = [0]
        for start in 0..<(w * h) where m[start] && label[start] == 0 {
            var stack = [start], n = 0
            label[start] = sizes.count
            while let i = stack.popLast() {
                n += 1
                let x = i % w, y = i / w
                for (nx, ny) in [(x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)] where nx >= 0 && nx < w && ny >= 0 && ny < h {
                    let j = ny * w + nx
                    if m[j] && label[j] == 0 { label[j] = sizes.count; stack.append(j) }
                }
            }
            sizes.append(n)
        }
        let least = w * h / 2000
        var t = (0..<(w * h)).map { label[$0] > 0 && sizes[label[$0]] >= least }
        guard whole else { return t }
        // Whole pieces: grown a little and their insides filled, so a gold coin on a gold pot — which differs from the pot
        // only at its rim and shading — is taken whole, not as an outline.
        for _ in 0..<4 { t = step(t, keep: false) }
        var outside = [Bool](repeating: false, count: w * h), stack: [Int] = []
        for x in 0..<w { stack += [x, (h - 1) * w + x] }
        for y in 0..<h { stack += [y * w, y * w + w - 1] }
        while let i = stack.popLast() {
            guard !outside[i], !t[i] else { continue }
            outside[i] = true
            let x = i % w, y = i / w
            if x > 0 { stack.append(i - 1) }; if x < w - 1 { stack.append(i + 1) }; if y > 0 { stack.append(i - w) }; if y < h - 1 { stack.append(i + w) }
        }
        return (0..<(w * h)).map { !outside[$0] && full[$0 * 4 + 3] > 128 }
    }
    /// How much of State0's face a drawn state has changed: the share of its body pixels with something new on them.
    public static func changedShare(_ state: [UInt8], body: [UInt8], width w: Int, height h: Int) -> Double {
        let t = treasure(state, base: body, width: w, height: h, whole: false)
        var all = 0, changed = 0
        for i in 0..<(w * h) where body[i * 4 + 3] > 128 { all += 1; if t[i] || state[i * 4 + 3] <= 128 { changed += 1 } }
        return Double(changed) / Double(max(1, all))
    }
    /// A state drawn whole (a safe's, a piggy bank's) with its body put back exactly: State0's own pixels wherever the
    /// drawing has nothing new on it, so the body never drifts from state to state.
    public static func restored(_ state: [UInt8], body: [UInt8], width w: Int, height h: Int) -> [UInt8] {
        let t = treasure(state, base: body, width: w, height: h)
        var out = state
        for i in 0..<(w * h) where body[i * 4 + 3] > 128 && !t[i] { for c in 0..<4 { out[i * 4 + c] = body[i * 4 + c] } }
        return out
    }
    /// The front lip a heap goes in behind, per column: where the heap's first run from the top meets the body below it,
    /// fitted with one smooth curve (a mouth's front edge is an arc or a straight edge) and carried flat past its ends.
    static func lip(treasure t: [Bool], base: [UInt8], width w: Int, height h: Int) -> [Int]? {
        var pts: [(x: Double, y: Double)] = []
        for x in 0..<w {
            guard let top = (0..<h).first(where: { t[$0 * w + x] }) else { continue }
            var y = top
            while y < h && t[y * w + x] { y += 1 }
            if y < h, base[(y * w + x) * 4 + 3] > 128 { pts.append((Double(x), Double(y))) }
        }
        guard pts.count >= w / 20 else { return nil }
        // y = a + b·x + c·x², least squares, twice — the second time without the points the first fit missed by over 3%.
        func fit(_ p: [(x: Double, y: Double)]) -> (Double, Double, Double)? {
            var s = [Double](repeating: 0, count: 7)
            for q in p { let u = q.x / Double(w); s[0] += 1; s[1] += u; s[2] += u * u; s[3] += u * u * u; s[4] += u * u * u * u; s[5] += q.y; s[6] += q.y * u }
            let s7 = p.reduce(0) { $0 + $1.y * ($1.x / Double(w)) * ($1.x / Double(w)) }
            let m = [[s[0], s[1], s[2], s[5]], [s[1], s[2], s[3], s[6]], [s[2], s[3], s[4], s7]]
            func det(_ a: [[Double]]) -> Double { a[0][0] * (a[1][1] * a[2][2] - a[1][2] * a[2][1]) - a[0][1] * (a[1][0] * a[2][2] - a[1][2] * a[2][0]) + a[0][2] * (a[1][0] * a[2][1] - a[1][1] * a[2][0]) }
            let a = m.map { Array($0.prefix(3)) }, d = det(a)
            guard abs(d) > 1e-12 else { return nil }
            func col(_ c: Int) -> [[Double]] { a.enumerated().map { r in r.element.enumerated().map { $0.offset == c ? m[r.offset][3] : $0.element } } }
            return (det(col(0)) / d, det(col(1)) / d, det(col(2)) / d)
        }
        // Spill pouring over the lip carries a column's run on down: kept only the points near the most common row first.
        let ys = pts.map(\.y).sorted(), mid = ys[ys.count / 2]
        let near = pts.filter { abs($0.y - mid) < 0.06 * Double(h) }
        guard near.count >= w / 20, var f = fit(near) else { return nil }
        let kept = near.filter { q in let u = q.x / Double(w); return abs(f.0 + f.1 * u + f.2 * u * u - q.y) < 0.03 * Double(h) }
        if kept.count >= w / 20, let g = fit(kept) { f = g }
        let x0 = Int(kept.first?.x ?? pts.first!.x), x1 = Int(kept.last?.x ?? pts.last!.x)
        return (0..<w).map { x in let u = Double(min(max(x, x0), x1)) / Double(w); return min(h, max(0, Int((f.0 + f.1 * u + f.2 * u * u).rounded()))) }
    }
    /// The parts, from State0 (`empty`), the open pot (`open`, nil for one without a lid) and the pot heaped full (`full`),
    /// all on one canvas — `open` and `full` laid on `empty` here, by the body below its rim. Nil when the treasure cannot
    /// be told from the pot.
    public static func parts(empty: [UInt8], open: [UInt8]?, full: [UInt8], lid: [UInt8]?, width w: Int, height h: Int) -> Parts? {
        let o = open.map { matched($0, to: empty, width: w, height: h, rows: 0.45...1) }
        // The body: State0 wherever its lid is not; under its lid, the open pot's mouth.
        var body = lid.map { withoutLid(empty, lid: $0) } ?? empty
        if let lid, let o { for i in 0..<(w * h) where lid[i * 4 + 3] > 128 && body[i * 4 + 3] <= 128 { for c in 0..<4 { body[i * 4 + c] = o[i * 4 + c] } } }
        let base = o ?? empty
        let f = matched(full, to: base, width: w, height: h, rows: 0.45...1)
        let t = treasure(f, base: base, width: w, height: h)
        guard t.contains(true), let l = lip(treasure: treasure(f, base: base, width: w, height: h, whole: false), base: base, width: w, height: h) else { return nil }
        var heap = [UInt8](repeating: 0, count: w * h * 4), front = heap
        for i in 0..<(w * h) where t[i] { for c in 0..<4 { if i / w < l[i % w] { heap[i * 4 + c] = f[i * 4 + c] } else { front[i * 4 + c] = f[i * 4 + c] } } }
        // How far it stands above where the lid rests (or the lip, without one).
        guard let tb = box(heap, width: w, height: h) else { return nil }
        let rest = lid.flatMap { box($0, width: w, height: h) }.map { $0.y + $0.h } ?? (l.min() ?? h)
        return Parts(body: body, lid: lid, heap: heap, front: front, lip: l, rise: max(0, rest - tb.y), width: w, height: h)
    }
    /// State `k` of the six, put together from the parts as the rigs move them: the heap sunk behind the front lip by what
    /// is not shown yet, the spill only at State4 (one side) and State5 (all of it),
    /// and the lid laid on what is under it with a soft shadow beneath. State0 is State0 itself.
    public static func state(_ k: Int, of p: Parts) -> [UInt8] {
        let w = p.width, h = p.height
        var out = p.body
        if k == 0 { if let lid = p.lid { LayerizeAssembly.over(&out, lid) }; return out }
        let sink = Int((Double(p.rise) * (1 - shown(k))).rounded())
        // The heap sunk into the mouth, hidden below the front lip.
        var heap = [UInt8](repeating: 0, count: w * h * 4)
        for y in 0..<(h - sink) { for x in 0..<w {
            let i = (y * w + x) * 4
            guard p.heap[i + 3] > 0, y + sink < p.lip[x] else { continue }
            for c in 0..<4 { heap[((y + sink) * w + x) * 4 + c] = p.heap[i + c] }
        } }
        LayerizeAssembly.over(&out, heap)
        if k >= levels - 1 {
            // The spill: at State4 the side with more of it, at State5 all of it.
            var spill = p.front
            if k == levels - 1 {
                var left = 0, right = 0
                for i in 0..<(w * h) where p.front[i * 4 + 3] > 128 { if i % w < w / 2 { left += 1 } else { right += 1 } }
                for i in 0..<(w * h) where (i % w < w / 2) != (left >= right) { spill[i * 4 + 3] = 0 }
            }
            LayerizeAssembly.over(&out, spill)
        }
        guard let lid = p.lid, let laid = placeLid(on: out, lid: lid, width: w, height: h, state: k) else { return out }
        return shaded(laid.px, under: laid.lid, width: w, height: h)
    }
    /// A soft shadow cast by a lid on what is just under it: darker at its edge, gone a tenth of the lid's height below.
    static func shaded(_ px: [UInt8], under lid: [UInt8], width w: Int, height h: Int) -> [UInt8] {
        guard let l = box(lid, width: w, height: h) else { return px }
        var out = px
        let reach = max(3, l.h / 10)
        for x in l.x..<(l.x + l.w) {
            guard let bottom = (l.y..<(l.y + l.h)).last(where: { lid[($0 * w + x) * 4 + 3] > 128 }) else { continue }
            for d in 1...reach where bottom + d < h {
                let i = ((bottom + d) * w + x) * 4
                guard lid[i + 3] <= 128, out[i + 3] > 0 else { continue }
                let k = 0.55 + 0.45 * Double(d) / Double(reach)
                for c in 0..<3 { out[i + c] = UInt8(Double(out[i + c]) * k) }
            }
        }
        return out
    }

    /// `state` laid on `empty`, both straight RGBA on the same `w` by `h` canvas, by its foot's band — or, `top`, by its
    /// top's.
    public static func registered(_ state: [UInt8], to empty: [UInt8], width w: Int, height h: Int, top: Bool = false) -> [UInt8] {
        guard let f = foot(state, width: w, height: h, top: top), let e = foot(empty, width: w, height: h, top: top), f.width > 0 else { return state }
        let k = e.width / f.width
        // Already in place (to a pixel or two of resampling): left alone, so laying again never blurs it.
        guard abs(k - 1) > 0.01 || abs(f.cx - e.cx) >= 2 || abs(f.end - e.end) >= 2 else { return state }
        let scaled = FrameKit.resized(FrameKit.Piece(px: state, w: w, h: h), Int((Double(w) * k).rounded()), Int((Double(h) * k).rounded()))
        var out = [UInt8](repeating: 0, count: w * h * 4)
        FrameKit.over(&out, width: w, scaled, at: Int((e.cx - f.cx * k).rounded()), Int((Double(e.end) - Double(f.end) * k).rounded()))
        return out
    }
}

/// Player-facing words and file names never say "free": production says "bonus games" (legal). Whole words
/// only, so "freeze" stays and "free spins" goes; a game's own title is not run through it.
public enum Wording {
    public static func noFree(_ t: String) -> String {
        t.replacingOccurrences(of: #"(?i)\bfree[ -]?(games?|spins?)\b"#, with: "bonus games", options: .regularExpression)
         .replacingOccurrences(of: #"(?i)\bfree\b"#, with: "bonus", options: .regularExpression)
    }
    /// For camel-case names: "freeSpinsCounter" → "bonusGamesCounter", "freezeMeter" untouched.
    public static func noFreeName(_ n: String) -> String {
        n.replacingOccurrences(of: #"(?<![a-zA-Z])[Ff]ree(Games|Spins|games|spins|Game|Spin)?(?![a-z])"#, with: "bonusGames", options: .regularExpression)
         .replacingOccurrences(of: #"(?<=[a-z])Free(Games|Spins|Game|Spin)?(?![a-z])"#, with: "BonusGames", options: .regularExpression)
    }
}

/// A piece of a game's static art that no dedicated generator makes, as Gemini plans it from the GDD
/// (ConceptPlan): what it is and looks like, its shape, size, lettering and states. Drawn by the generic
/// generator the way the dedicated ones are — a grey template by shape, painted in the set's material by
/// GPT Image, each state an edit of the first. Code keeps what must be exact (the bezel, a wheel's wedges);
/// this covers the rest — meters, collection areas, glass covers, counters, sell screens — and whatever a
/// new GDD invents.
public struct ConceptPiece: Codable, Equatable, Sendable {
    public var name: String          // the studio's file name: "base_interface_multiplierMeter"
    public var what: String          // what it is in the game, from the GDD
    public var look: String          // how it should look
    public var shape: String         // panel | bar | button | plaque | ring | disc | lettering | free
    public var width: Int, height: Int
    public var lettering: String     // words lettered into it ("" for none) — never an amount the engine prints
    public var states: [String]      // its states after the first, as the GDD has them ("lit", "full"); [] for one image
    public var source: String        // the GDD's own words it comes from
    public var standard = false      // the studio's own convention (a logo, a sell screen), not read off the GDD
    /// Set images it is drawn from, by id ("HP1": the hero for the key art), attached after the reel frame.
    public var refs: [String]? = nil

    public static let shapes = ["panel", "bar", "button", "plaque", "ring", "disc", "lettering", "free"]

    /// A piece as code will draw it: a studio name, a known shape, a size GPT Image takes (multiples of 16,
    /// no longer than 3:1, at most 2048 a side), at most five states, and never "free" in a name or a word.
    public func normalised() -> ConceptPiece {
        var p = self
        let noFree = Wording.noFree
        let words = Wording.noFreeName(name).split { !$0.isLetter && !$0.isNumber && $0 != "_" && $0 != "-" }.joined()
        p.name = words.isEmpty ? "base_interface_piece" : String(words.prefix(80))
        if !p.name.contains("_") { p.name = "base_interface_" + p.name }
        p.what = noFree(what); p.look = noFree(look); p.lettering = noFree(lettering).uppercased(); p.source = source
        p.shape = Self.shapes.contains(shape.lowercased()) ? shape.lowercased() : "free"
        var w = max(64, min(2048, width)), h = max(64, min(2048, height))
        if w > 3 * h { h = (w + 2) / 3 } else if h > 3 * w { w = (h + 2) / 3 }
        p.width = (w + 15) / 16 * 16; p.height = (h + 15) / 16 * 16
        if p.width > 3 * p.height { p.height = (p.width / 3 + 15) / 16 * 16 }
        if p.height > 3 * p.width { p.width = (p.height / 3 + 15) / 16 * 16 }
        p.states = Array(states.map { noFree($0).trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }.prefix(5))
        return p
    }
    /// A state's file name: `<name>-<state>` in camel case ("base_interface_glass-shattered").
    public func stateName(_ state: String) -> String { "\(name)-\(PopUps.key(state))" }

    /// Its grey template on the backing, by shape; nil for lettering and free shapes, drawn on a plain canvas.
    static func template(_ p: ConceptPiece, backing b: RGB8) -> [UInt8]? {
        switch p.shape {
        case "panel": return PopUps.template(PopUps.Piece(name: "", kind: .panel, text: "", w: p.width, h: p.height), backing: b)
        case "bar": return PopUps.template(PopUps.Piece(name: "", kind: .bar, text: "", w: p.width, h: p.height), backing: b)
        case "button", "plaque": return PopUps.template(PopUps.Piece(name: "", kind: .button, text: "", w: p.width, h: p.height), backing: b)
        case "ring", "disc":
            // A ring or disc as wide as the piece's shorter side, centred.
            let n = min(p.width, p.height)
            let sq = p.shape == "disc" ? WheelArt.discTemplate(size: n, share: 0.9, backing: b) : ring(n, backing: b)
            var out = [UInt8](repeating: 255, count: p.width * p.height * 4)
            for i in 0..<(p.width * p.height) { out[i * 4] = b.r; out[i * 4 + 1] = b.g; out[i * 4 + 2] = b.b }
            let ox = (p.width - n) / 2, oy = (p.height - n) / 2
            for y in 0..<n { for x in 0..<n { for c in 0..<4 { out[((y + oy) * p.width + x + ox) * 4 + c] = sq[(y * n + x) * 4 + c] } } }
            return out
        default: return nil
        }
    }
    static func ring(_ n: Int, backing b: RGB8) -> [UInt8] {
        let c = Double(n) / 2, inner = 0.62 * c, outer = 0.95 * c
        var px = [UInt8](repeating: 255, count: n * n * 4)
        for y in 0..<n { for x in 0..<n {
            let i = (y * n + x) * 4, r = ((Double(x) + 0.5 - c) * (Double(x) + 0.5 - c) + (Double(y) + 0.5 - c) * (Double(y) + 0.5 - c)).squareRoot()
            let g: UInt8? = r >= inner && r <= outer ? UInt8(130 + 60 * (c - Double(y)) / c) : nil
            px[i] = g ?? b.r; px[i + 1] = g ?? b.g; px[i + 2] = g ?? b.b
        } }
        return px
    }
}

/// Every static asset a game needs, as GDD to Assets will make it — and what it needs that nothing makes yet —
/// with the files each is, who makes it and about what it costs, so the whole set is seen before a cent is spent.
public enum AssetChecklist {
    public struct Item: Equatable, Sendable {
        public var group: String, name: String, what: String
        public var files: [String]           // what it is on disk once made (a piece's states too)
        public var maker: String             // "Symbols", "Reel area", "Gemini concept", …; "" when nothing makes it yet
        public var cost: Double              // about, for what is not made yet
        public var supported: Bool { !maker.isEmpty }
    }
    /// GPT Image's cost for a piece, measured (2026-10-04): $0.06 a megapixel's worth at least, rising with the
    /// square root of the size — $0.12 at 2048², $0.17 for a 3168×2304 bezel asked at 8 MP.
    public static func gpt(_ w: Int, _ h: Int) -> Double { 0.06 * max(1, Double(w * h) / 1_048_576).squareRoot() }

    /// Bonus games, one definition for the pop-ups, the checklist and the intro cards: a bonus grid read or typed,
    /// or — with no other mode — bonus symbols (a Loot-Link-only game has no "BONUS GAMES AWARDED!").
    public static func hasBonusGames(jobs: [AssetJob], layout: ReelLayout?) -> Bool {
        guard let l = layout else { return jobs.contains { $0.role == .bonus } }
        if l.grids.contains(where: { $0.mode.hasPrefix("bonus") }) { return true }
        return !l.grids.contains { $0.mode != "base" } && jobs.contains { $0.role == .bonus }
    }

    public static func items(jobs: [AssetJob], layout: ReelLayout?, jackpots names: [String], hasBonus: Bool, standard: [ConceptPiece]? = nil) -> [Item] {
        var out: [Item] = []
        for j in jobs where j.kind == .symbol {
            out.append(Item(group: "Symbols", name: j.id, what: j.title, files: ["\(j.id).png"], maker: "Symbols", cost: 0.10))
        }
        for j in jobs where j.kind == .background {
            out.append(Item(group: "Backgrounds", name: j.id, what: j.title, files: ["\(j.id).png"], maker: "Backgrounds", cost: 0.15))
        }
        guard let l = layout, l.base != nil else {
            out.append(Item(group: "Reel area", name: "reels", what: "the reels' size — the document gives none: set the game's structure", files: [], maker: "", cost: 0))
            return out
        }
        for (i, m) in l.fileModes.enumerated() {
            let a = ReelArea(l, grid: m.grid)
            out.append(Item(group: "Reel area", name: "\(m.name)_interface_bezel", what: "\(m.grid.rows)×\(m.grid.reels) bezel and dividers\(m.grid.independent ? ", each cell its own" : "")",
                            files: ["\(m.name)_interface_bezel.png", "\(m.name)_interface_dividers_rmbg.png"], maker: "Reel area", cost: i == 0 ? gpt(a.width, a.height) * 1.3 : 0))
            out.append(Item(group: "Reel area", name: "\(m.name)_interface_reelTexture", what: "reel texture and reel fade",
                            files: ["\(m.name)_interface_reelTexture_rmbg.png", "\(m.name)_interface_reelFade_rmbg.png"], maker: "Reel area", cost: i == 0 ? gpt(2048, 1365) : 0))
        }
        if l.extras.contains(where: { $0.what == "jackpot table" }), !names.isEmpty {
            let sheet = JackpotMeters(count: names.count)
            out.append(Item(group: "Jackpots", name: "shared_interface_jackpotTable", what: "the jackpot meters, drawn together, a plaque per tier: " + names.joined(separator: ", "),
                            files: ["shared_interface_jackpotTable.png"], maker: "Jackpot meters", cost: gpt(sheet.width, sheet.height)))
        }
        if let pots = l.extras.first(where: { $0.what == "pots" }) {
            // As many as the generator draws: the GDD's number, else one per bonus symbol.
            let n = pots.count ?? max(1, jobs.filter { $0.role == .bonus }.count)
            for i in 0..<n {
                let words = (l.potFeatures ?? []).indices.contains(i) ? l.potFeatures![i] : ""
                out.append(Item(group: "Pots", name: PotStates.name(pot: i, of: n, state: 0).replacingOccurrences(of: "-State0Idle", with: ""),
                                what: "pot \(i + 1), State0 to State\(PotStates.levels)" + (words.isEmpty ? "" : " — \(words)"),
                                files: (0...PotStates.levels).map { "\(PotStates.name(pot: i, of: n, state: $0)).png" }, maker: "Pots", cost: Double(PotStates.levels + 2) * gpt(1024, PotStates.height(1024))))
                if n > 1 { out.append(Item(group: "Pots", name: PotStates.plaqueName(pot: i), what: words.isEmpty ? "plaque, plain" : "plaque: \(words)",
                                           files: ["\(PotStates.plaqueName(pot: i)).png"], maker: "Pots", cost: gpt(1024, 384))) }
                if let boost = l.potBoost {
                    out.append(Item(group: "Pots", name: PotStates.boostedName(pot: i, of: n), what: "pot \(i + 1) with the Power Bet on: \(boost)",
                                    files: ["\(PotStates.boostedName(pot: i, of: n)).png"], maker: "Pots", cost: gpt(1024, PotStates.height(1024))))
                }
            }
        }
        for (wi, w) in (l.wheels ?? []).enumerated() {
            let prefix = wi == 0 ? "wheelSpin" : "wheelSpin\(wi + 1)"
            if wi == 0 {
                out.append(Item(group: "Wheels", name: "wheelSpin_interface_wheelFrame", what: "rim, hub and pointer, shared by the game's wheels",
                                files: ["wheelSpin_interface_wheelFrame.png", "wheelSpin_interface_wheelHub.png", "wheelSpin_interface_winIndicator.png"],
                                maker: "Wheels", cost: gpt(2048, 2048) * 1.3 + 2 * gpt(512, 512)))
            }
            let labels = WheelRules.labels(w, jackpots: names)
            let distinct = labels.reduce(into: [String]()) { if !$0.contains($1) { $0.append($1) } }
            out.append(Item(group: "Wheels", name: "\(prefix)_interface_wedge", what: "\(w.name): " + distinct.joined(separator: ", "),
                            files: distinct.map { "\(prefix)_interface_wedge-\(PopUps.key($0)).png" }, maker: "Wheels", cost: Double(distinct.count) * gpt(1024, 1024)))
        }
        for p in PopUps.plan(l, jackpots: names, bonus: hasBonus) {
            out.append(Item(group: "Pop-ups", name: p.name, what: p.text.isEmpty ? p.kind.rawValue : p.text.replacingOccurrences(of: "\n", with: " "),
                            files: ["\(p.name).png"], maker: "Pop-ups", cost: gpt(p.w, p.h)))
        }
        if l.extras.contains(where: { $0.what == "jackpot table" }), !names.isEmpty {
            out.append(Item(group: "Jackpots", name: "shared_meter", what: "each tier's meter, cut from the sheet: " + names.joined(separator: ", "),
                            files: names.map { "shared_meter_\(PopUps.key($0)).png" }, maker: "Jackpot meters", cost: 0))
        }
        out.append(Item(group: "Fonts", name: "transition_font_totalWin", what: "the total-win number font: " + NumberFont.glyphs.joined(separator: " "),
                        files: ["transition_font_totalWin.png"], maker: "Number font", cost: gpt(NumberFont.size.w, NumberFont.size.h)))
        for c in (standard ?? []) + StandardPieces.without(l.concepts ?? [], standard ?? []) {
            out.append(Item(group: c.standard ? "Studio pieces" : "From the GDD", name: c.name, what: c.what + (c.states.isEmpty ? "" : " (states: \(c.states.joined(separator: ", ")))"),
                            files: ["\(c.name).png"] + c.states.map { "\(c.stateName($0)).png" }, maker: "Gemini concept", cost: Double(1 + c.states.count) * gpt(c.width, c.height)))
        }
        if (standard ?? []).contains(where: { $0.name == "shared_logo_master" }) {
            out.append(Item(group: "Lobby and loading", name: "shared_preloader", what: "the loading screen and lobby icons, put together from the logo, the key art and the base background",
                            files: Composites.all.map { "\($0.name).png" } + ((standard ?? []).contains { $0.name == "shared_sellScreen_background" } ? ["shared_sellScreen_tutorialAvatar.png"] : []),
                            maker: "Composites", cost: 0))
        }
        // What the GDD has that nothing makes yet: said, not dropped.
        if l.concepts == nil {
            for e in l.extras where ["meters", "collection area", "extra reel"].contains(e.what) && !(e.what == "extra reel" && e.place == "above") {
                out.append(Item(group: "From the GDD", name: e.what, what: "\(e.count.map { "\($0) " } ?? "")\(e.what) \(e.place) — read from the GDD; Find What Else It Needs plans them",
                                files: [], maker: "", cost: 0))
            }
        }
        return out
    }
}

/// The pieces every game gets, and those a GDD's signals call for, that GDDs almost never list (asset inventory
/// of 10 shipped games, 2026-10-04: a logo in 9 of 10 and 2 of 56 GDDs; Power Bet UI in 8 of 10, signalled by
/// "Power Bet" in 31 GDDs; tutorials required by 35 GDDs). Drawn by the generic generator like Gemini's pieces.
public enum StandardPieces {
    /// The game's title for its logo: the document's name without its number and file words ("9001 Example
    /// Pots GDD (Google Doc)" → "Example Pots"), or the typed game's name.
    public static func title(_ game: String) -> String {
        var t = game.replacingOccurrences(of: #"\.(txt|docx?|md)$"#, with: "", options: .regularExpression)
        t = t.replacingOccurrences(of: #"\((Google Doc|DOCX)\)"#, with: "", options: .regularExpression)
        t = t.replacingOccurrences(of: #"(?i)\b(GDD|game design document)\b"#, with: "", options: .regularExpression)
        t = t.replacingOccurrences(of: #"^\s*\d+\s+"#, with: "", options: .regularExpression)
        return t.trimmingCharacters(in: .whitespacesAndNewlines.union(CharacterSet(charactersIn: "-–")))
    }

    /// Planned pieces with any a studio piece already makes taken out: a plan made before these existed drew a
    /// second logo and a second sell-screen panel (Tiki, 2026-10-04).
    public static func without(_ concepts: [ConceptPiece], _ standard: [ConceptPiece]) -> [ConceptPiece] {
        let has = { (n: String) in standard.contains { $0.name == n } }
        return concepts.filter { c in
            let n = c.name.lowercased()
            // The game's own logo planned again — not a feature's logo, which the plan asks for.
            if (n.contains("gamelogo") || n.hasSuffix("_logo") || n.contains("logomaster")) && has("shared_logo_master") { return false }
            if n.contains("sellscreen") && (n.contains("panel") || n.contains("background")) && has("shared_sellScreen_background") { return false }
            if n.contains("powerbet") && (n.contains("drawer") || n.contains("toggle")) && has("shared_powerBet_drawer") { return false }
            if n.contains("tutorial") && n.contains("background") && has("shared_tutorial_background") { return false }
            return !has(c.name)
        }
    }

    public static func pieces(game: String, gdd: String, layout: ReelLayout, hero: String?, bonusGames: Bool? = nil) -> [ConceptPiece] {
        let name = title(game), l = gdd.lowercased()
        func piece(_ n: String, _ what: String, _ look: String, _ shape: String, _ w: Int, _ h: Int, _ letters: String = "", refs: [String]? = nil) -> ConceptPiece {
            ConceptPiece(name: n, what: what, look: look, shape: shape, width: w, height: h, lettering: letters, states: [], source: "", standard: true, refs: refs).normalised()
        }
        var out: [ConceptPiece] = []
        // The game's own title, as it is — not run through the "free" wording — and none for a game not named yet.
        if !name.isEmpty && name.lowercased() != "untitled game" {
            var logo = piece("shared_logo_master", "the game's title logo, “\(name)”.", "Bold, dimensional display lettering of the title in the theme's richest colours and metal, an emblem of the theme worked into it, as a slot game's logo is.", "lettering", 2048, 1024)
            logo.lettering = name.uppercased(); logo.what = "the game's title logo, “\(name)”."
            out.append(logo)
        }
        if let hero {
            out.append(piece("shared_character_keyArt", "the full figure of the game's hero — the character or object in the attached symbol — for the logo, lobby icons and loading screen.",
                             "The same face, hair, crown and costume as the symbol, the whole figure from head to feet in a heroic three-quarter pose, lit dramatically.", "free", 1536, 2048, refs: [hero]))
        }
        if l.contains("power bet") || layout.grids.contains(where: { $0.mode.hasPrefix("power bet") }) {
            out += [piece("shared_sellScreen_background", "the blank panel of the Power Bet sell screen, where the player picks a boost.", "A grand plaque, its face plain and empty.", "panel", 720, 768),
                    piece("shared_sellScreen_playNowBtn", "the sell screen's play button.", "A raised, glowing button.", "button", 1024, 384, "PLAY NOW!"),
                    piece("shared_powerBet_drawer", "the Power Bet drawer that slides out beside the reels, holding the boost buttons.", "A tall panel, its header lettered.", "panel", 368, 608, "POWER BET"),
                    piece("shared_powerBet_toggleOff", "the Power Bet switch, off.", "A small toggle switch, dark.", "button", 512, 224, "OFF"),
                    piece("shared_powerBet_toggleOn", "the Power Bet switch, on.", "A small toggle switch, lit.", "button", 512, 224, "ON")]
        }
        // The intro splash: a card for each feature the game has, a little scene of it lettered with its name,
        // shown before play (9 of 10 shipped games) — from the structure, as GDDs never list the cards.
        var features: [(key: String, title: String, refs: [String]?)] = []
        if bonusGames ?? layout.grids.contains(where: { $0.mode.hasPrefix("bonus") }) { features.append(("bonusGames", "BONUS GAMES", nil)) }
        for g in layout.grids where ReelLayoutRules.holdModes.contains(g.mode) { features.append((PopUps.key(g.mode), g.mode.uppercased(), nil)) }
        for w in layout.wheels ?? [] where !w.name.hasPrefix("Bonus") { features.append((PopUps.key(w.name), w.name.uppercased(), nil)) }
        if layout.extras.contains(where: { $0.what == "pots" }) { features.append(("pots", "FILL THE POTS", nil)) }
        if layout.extras.contains(where: { $0.what == "hot reel" }) { features.append(("hotReel", "HOT REEL", nil)) }
        if layout.awards?.contains("one more chance") == true { features.append(("oneMoreChance", "ONE MORE CHANCE", nil)) }
        for f in features.prefix(4) {
            out.append(piece("shared_intro_featureCard-\(f.key)", "the intro screen's card for the game's \(f.title.capitalized) feature: a small, bright scene showing it at work on the reels.",
                             "A square card with a fine frame in the reel frame's material, the scene inside it, the feature's name lettered across its foot.", "panel", 512, 512, f.title, refs: hero.map { [$0] }))
        }
        if !features.isEmpty {
            out.append(piece("shared_intro_continueBtn", "the intro screen's CONTINUE button, blank: its words are laid on it in each language.", "A raised, glowing button, its face plain.", "button", 1024, 384))
        }
        if l.contains("tutorial") {
            out += [piece("shared_tutorial_background", "the blank panel the game's first-time tutorial cards appear on.", "A plain panel with a fine frame, its face empty.", "panel", 1024, 640),
                    piece("shared_tutorial_button", "the tutorial's button.", "A small raised button.", "button", 448, 208, "GOT IT!")]
        }
        return out
    }
}

